function renderProviderKeyCards(){const provider=cache.providers.find(x=>Number(x.id)===Number(providerKeyManager.providerId));if(!provider)return;const items=providerKeyManager.items,root=$('#providerKeyList'),defaultModel=provider.default_model||'全部渠道模型',defaultEgress=provider.ip_pool_node_id?(provider.ip_pool_node_name||'IP 池节点'):'本机直连';setProviderKeysEnabled(true);$('#providerKeysDefaults').innerHTML='<strong>渠道默认</strong><span class="provider-default-chip">模型：'+esc(defaultModel)+'</span><span class="provider-default-chip">出口：'+esc(defaultEgress)+'</span><span>Key 留空配置时自动继承。</span>';$('#providerKeysCount').textContent=items.length+' 张 Key 卡片 · '+items.filter(x=>x.enabled).length+' 张启用';$('#keyTabCount').textContent=String(items.length);if(!items.length){root.innerHTML='<div class="provider-key-empty"><strong>还没有 Key 卡片</strong><span>添加后才能让这个渠道参与新请求。</span></div>';return}root.innerHTML=items.map((key,index)=>providerKeyCardHTML(key,index,provider)).join('')}
function providerKeyCardHTML(key,index,provider){const isNew=!Number(key.id),status=providerKeyStatusMeta(key.status),shown=providerKeyManager.revealed.get(Number(key.id))||key.key_hint||'等待保存',title=key.name||key.key_hint||'新 Key',modelPlaceholder='继承渠道默认：'+(provider.default_model||'全部模型'),egress=key.egress_mode||'inherit',observed=key.last_tested_at?(new Date(key.last_tested_at).toLocaleString('zh-CN',{hour12:false})+(key.last_test_latency_ms?' · '+key.last_test_latency_ms+' ms':'')):'尚未测试',effective='有效配置：模型 '+providerKeyEffectiveModel(key,provider)+' · 出口 '+providerKeyEffectiveEgress(key,provider),inventory=isNew?'保存后可识别模型':((key.discovered_models||0)+' 个模型已识别'+(key.last_discovered_at?' · '+new Date(key.last_discovered_at).toLocaleString('zh-CN',{hour12:false}):''));return '<article class="provider-key-card '+(key.enabled===false?'off ':'')+(isNew?'new':'')+'" data-key-id="'+(key.id||0)+'"><div class="provider-key-head"><div class="provider-key-title"><strong>'+esc(title)+'</strong><code class="'+(providerKeyManager.revealed.has(Number(key.id))?'provider-key-revealed':'')+'">'+esc(shown)+'</code></div><div class="provider-key-status">'+badge(isNew?'待保存':status[0],isNew?'blue':status[1])+badge('#'+(index+1),'neutral')+'<label class="channel-switch"><input data-field="enabled" type="checkbox" '+(key.enabled===false?'':'checked')+'><span class="switch-track"><span></span></span><strong>'+(key.enabled===false?'已停用':'启用中')+'</strong></label></div></div><div class="provider-key-grid"><label class="field provider-key-secret"><span>'+(isNew?'API Key':'替换 API Key（可留空）')+'</span><input data-field="apiKey" type="password" autocomplete="new-password" placeholder="'+(isNew?'输入完整 API Key':'留空保留现有 Key')+'" '+(isNew?'required':'')+'><small>保存后仅显示开头和结尾。</small></label><label class="field"><span>备注名</span><input data-field="name" value="'+esc(key.name||'')+'" placeholder="例如 主号 / GPT 专用"></label><label class="field"><span>模型覆盖</span><input data-field="model" list="providerKeyModels-'+(key.id||'new')+'" value="'+esc(key.model||'')+'" placeholder="'+esc(modelPlaceholder)+'"><datalist id="providerKeyModels-'+(key.id||'new')+'">'+providerModelOptions(provider.id)+'</datalist><small>清空表示继承渠道默认。</small></label><label class="field"><span>出口规则</span><select data-field="egressMode" onchange="providerKeyEgressChanged(this)"><option value="inherit" '+(egress==='inherit'?'selected':'')+'>继承渠道默认</option><option value="direct" '+(egress==='direct'?'selected':'')+'>强制本机直连</option><option value="node" '+(egress==='node'?'selected':'')+'>指定 IP 池节点</option></select></label><label class="field"><span>指定节点</span><select data-field="nodeID" '+(egress==='node'?'':'disabled')+'>'+providerKeyNodeOptions(key.ip_pool_node_id||'')+'</select><small>仅“指定节点”时生效。</small></label></div><div class="provider-key-foot"><div class="provider-key-observation" title="'+esc((key.last_error||'')+' '+effective)+'">'+esc(key.last_error||observed)+' · '+esc(effective)+' · '+esc(inventory)+'</div><div class="provider-key-actions">'+(isNew?'':'<span class="provider-key-order"><button class="btn btn-ghost btn-sm" type="button" title="上移" aria-label="上移 '+esc(title)+'" onclick="moveProviderKey('+key.id+',-1)" '+(index===0?'disabled':'')+'>'+icon('i-caret-up')+'</button><button class="btn btn-ghost btn-sm" type="button" title="下移" aria-label="下移 '+esc(title)+'" onclick="moveProviderKey('+key.id+',1)" '+(index===providerKeyManager.items.length-1?'disabled':'')+'>'+icon('i-caret-down')+'</button></span><button class="btn btn-secondary btn-sm" type="button" onclick="revealProviderKey('+key.id+',false)">'+icon('i-eye')+'查看</button><button class="btn btn-secondary btn-sm" type="button" onclick="revealProviderKey('+key.id+',true)">'+icon('i-copy')+'复制</button><button class="btn btn-secondary btn-sm" type="button" onclick="discoverProviderKeyCard('+key.id+',this)">'+icon('i-refresh')+'识别模型</button><button class="btn btn-secondary btn-sm" type="button" onclick="testProviderKeyCard('+key.id+',this)">'+icon('i-activity')+'测试</button>')+'<button class="btn btn-primary btn-sm" type="button" onclick="saveProviderKeyCard('+(key.id||0)+',this)">'+icon('i-check')+(isNew?'添加 Key':'保存')+'</button>'+(isNew?'<button class="btn btn-ghost btn-sm" type="button" onclick="cancelNewProviderKey()">取消</button>':'<button class="btn btn-danger btn-sm" type="button" onclick="deleteProviderKeyCard('+key.id+')">删除</button>')+'</div></div></article>'}
function providerKeyEgressChanged(select){const card=select.closest('.provider-key-card'),node=card.querySelector('[data-field="nodeID"]');node.disabled=select.value!=='node'}
function addProviderKeyCard(){if(!providerKeyManager.providerId)return notice('请先保存渠道，再添加 Key',true);if(providerKeyDirty)return notice('请先保存或放弃未保存的 Key 修改，再添加 Key',true);if(providerKeyManager.items.some(x=>!Number(x.id)))return notice('请先保存或取消当前新 Key',true);const provider=cache.providers.find(x=>Number(x.id)===Number(providerKeyManager.providerId));providerKeyManager.items.push({id:0,name:'',key_hint:'新 Key',model:'',egress_mode:'inherit',enabled:true,sort_order:providerKeyManager.items.length,status:'untested',effective_model:provider?.default_model||'',effective_egress:provider?.ip_pool_node_id?'node':'direct'});renderProviderKeyCards();providerKeyDirty=true;const card=$('#providerKeyList .provider-key-card.new');if(card)card.dataset.dirty='1';setTimeout(()=>card?.querySelector('input[data-field="apiKey"]')?.focus(),40)}
function cancelNewProviderKey(){providerKeyManager.items=providerKeyManager.items.filter(x=>Number(x.id));$('#providerKeyList .provider-key-card.new')?.remove();providerKeyDirty=$$('#providerKeyList .provider-key-card[data-dirty="1"]').length>0;const items=providerKeyManager.items;if(!items.length){renderProviderKeyCards();return}$('#providerKeysCount').textContent=items.length+' 张 Key 卡片 · '+items.filter(x=>x.enabled).length+' 张启用';$('#keyTabCount').textContent=String(items.length)}
function providerKeyCardPayload(card,existing){const mode=card.querySelector('[data-field="egressMode"]').value,nodeID=Number(card.querySelector('[data-field="nodeID"]').value)||0,payload={name:card.querySelector('[data-field="name"]').value.trim(),model:card.querySelector('[data-field="model"]').value.trim().toLowerCase(),egress_mode:mode,ip_pool_node_id:mode==='node'?nodeID:0,enabled:card.querySelector('[data-field="enabled"]').checked};const raw=card.querySelector('[data-field="apiKey"]').value.trim();if(raw)payload.api_key=raw;if(!existing&&!raw)throw Error('API Key 不能为空');if(mode==='node'&&!nodeID)throw Error('请选择 IP 池节点');return payload}
const providerKeyCardHTMLBase=providerKeyCardHTML;providerKeyCardHTML=function(key,index,provider){let html=providerKeyCardHTMLBase(key,index,provider),models=Array.isArray(key.models)?key.models:[];if(!Number(key.id)||!models.length)return html;const selected=models.filter(x=>x.enabled).length,picker='<section class="provider-key-models"><header><strong>此 Key 可用模型</strong><span class="muted">已选 '+selected+' / '+models.length+'</span></header><div class="provider-key-model-list">'+models.map(x=>'<label class="provider-key-model" title="'+esc(x.display_name||x.model)+'"><input data-key-model type="checkbox" value="'+esc(x.model)+'" '+(x.enabled?'checked':'')+'><span>'+esc(x.model)+'</span></label>').join('')+'</div></section>';return html.replace('<div class="provider-key-foot">',picker+'<div class="provider-key-foot">')}
const providerKeyCardPayloadBase=providerKeyCardPayload;providerKeyCardPayload=function(card,existing){const payload=providerKeyCardPayloadBase(card,existing),models=[...card.querySelectorAll('[data-key-model]:checked')].map(x=>x.value);if(card.querySelector('[data-key-model]'))payload.models=models;return payload}
async function saveProviderKeyCard(id,button){const card=button.closest('.provider-key-card'),otherDirty=$$('#providerKeyList .provider-key-card[data-dirty="1"]').some(item=>item!==card),existing=Number(id)>0,original=button.innerHTML,providerId=Number(providerKeyManager.providerId),generation=providerPanelGeneration;if(otherDirty&&!confirm('其他 Key 卡片也有未保存修改。保存当前卡片会丢弃其他修改，确认继续？'))return;let payload;try{payload=providerKeyCardPayload(card,existing)}catch(e){return notice(e.message,true)}button.disabled=true;button.textContent='保存中…';try{await api('/api/admin/providers/'+providerId+'/keys'+(existing?'/'+id:''),{method:existing?'PATCH':'POST',body:JSON.stringify(payload)});if(generation!==providerPanelGeneration||Number(providerKeyManager.providerId)!==providerId)return;notice(existing?'Key 卡片已保存':'Key 已添加');await loadProviderKeys(generation,providerId);await load()}catch(e){if(generation===providerPanelGeneration&&Number(providerKeyManager.providerId)===providerId)notice('保存 Key 失败：'+e.message,true)}finally{if(button.isConnected){button.disabled=false;button.innerHTML=original}}}
async function deleteProviderKeyCard(id){const key=providerKeyManager.items.find(x=>Number(x.id)===Number(id)),card=$('#providerKeyList .provider-key-card[data-key-id="'+id+'"]'),otherDirty=$$('#providerKeyList .provider-key-card[data-dirty="1"]').some(item=>item!==card),providerId=Number(providerKeyManager.providerId),generation=providerPanelGeneration;if(otherDirty&&!confirm('其他 Key 卡片有未保存修改。删除后重新加载会丢弃这些修改，确认继续？'))return;if(!confirm('确认删除 '+(key?.name||key?.key_hint||'这张 Key')+'？\n\n删除后无法恢复，且不会自动回退到隐藏旧 Key。'))return;try{await api('/api/admin/providers/'+providerId+'/keys/'+id,{method:'DELETE'});if(generation!==providerPanelGeneration||Number(providerKeyManager.providerId)!==providerId)return;notice('Key 卡片已删除');await loadProviderKeys(generation,providerId);await load()}catch(e){if(generation===providerPanelGeneration&&Number(providerKeyManager.providerId)===providerId)notice('删除失败：'+e.message,true)}}
async function revealProviderKey(id,copy){const providerId=Number(providerKeyManager.providerId),generation=providerPanelGeneration;try{const d=await api('/api/admin/providers/'+providerId+'/keys/'+id+'/reveal',{method:'POST',body:'{}'});if(generation!==providerPanelGeneration||Number(providerKeyManager.providerId)!==providerId)return;if(copy){await copyText(d.api_key);return}providerKeyManager.revealed.set(Number(id),d.api_key);const code=$('#providerKeyList .provider-key-card[data-key-id="'+id+'"] code');if(code){code.textContent=d.api_key;code.classList.add('provider-key-revealed')}setTimeout(()=>{if(generation!==providerPanelGeneration||Number(providerKeyManager.providerId)!==providerId||!providerKeyManager.revealed.delete(Number(id)))return;const key=providerKeyManager.items.find(item=>Number(item.id)===Number(id)),current=$('#providerKeyList .provider-key-card[data-key-id="'+id+'"] code');if(current){current.textContent=key?.key_hint||'';current.classList.remove('provider-key-revealed')}},10000)}catch(e){if(generation===providerPanelGeneration&&Number(providerKeyManager.providerId)===providerId)notice('读取 Key 失败：'+e.message,true)}}
async function testProviderKeyCard(id,button){if(providerKeyDirty)return notice('请先保存或放弃未保存的 Key 修改，再执行测试',true);const original=button.innerHTML,providerId=Number(providerKeyManager.providerId),generation=providerPanelGeneration;button.disabled=true;button.textContent='测试中…';try{const d=await api('/api/admin/providers/'+providerId+'/keys/'+id+'/test',{method:'POST',body:'{}'});if(generation!==providerPanelGeneration||Number(providerKeyManager.providerId)!==providerId)return;notice('Key 测试通过：'+d.model_count+' 个模型 · '+d.latency_ms+' ms');await loadProviderKeys(generation,providerId)}catch(e){if(generation===providerPanelGeneration&&Number(providerKeyManager.providerId)===providerId){notice('Key 测试失败：'+e.message,true);await loadProviderKeys(generation,providerId)}}finally{if(button.isConnected){button.disabled=false;button.innerHTML=original}}}
async function discoverProviderKeyCard(id,button){if(providerKeyDirty)return notice('请先保存或放弃未保存的 Key 修改，再识别模型',true);const original=button.innerHTML,providerId=Number(providerKeyManager.providerId),generation=providerPanelGeneration;button.disabled=true;button.textContent='识别中…';try{const d=await api('/api/admin/providers/'+providerId+'/keys/'+id+'/discover-models',{method:'POST',body:'{}'});if(generation!==providerPanelGeneration||Number(providerKeyManager.providerId)!==providerId)return;notice('识别完成：'+d.key.discovered+' 个模型 · '+d.key.latency_ms+' ms');await loadProviderKeys(generation,providerId)}catch(e){if(generation===providerPanelGeneration&&Number(providerKeyManager.providerId)===providerId){notice('Key 模型识别失败：'+e.message,true);await loadProviderKeys(generation,providerId)}}finally{if(button.isConnected){button.disabled=false;button.innerHTML=original}}}
async function moveProviderKey(id,direction){if(providerKeyDirty)return notice('请先保存或放弃未保存的 Key 修改，再调整顺序',true);const items=providerKeyManager.items.filter(x=>Number(x.id)),index=items.findIndex(x=>Number(x.id)===Number(id)),target=index+direction,providerId=Number(providerKeyManager.providerId),generation=providerPanelGeneration;if(index<0||target<0||target>=items.length)return;const a=items[index],b=items[target],aOrder=Number(a.sort_order),bOrder=Number(b.sort_order);try{await Promise.all([api('/api/admin/providers/'+providerId+'/keys/'+a.id,{method:'PATCH',body:JSON.stringify({sort_order:bOrder})}),api('/api/admin/providers/'+providerId+'/keys/'+b.id,{method:'PATCH',body:JSON.stringify({sort_order:aOrder})})]);if(generation!==providerPanelGeneration||Number(providerKeyManager.providerId)!==providerId)return;await loadProviderKeys(generation,providerId);notice('Key 顺序已更新')}catch(e){if(generation===providerPanelGeneration&&Number(providerKeyManager.providerId)===providerId)notice('调整顺序失败：'+e.message,true)}}
function openProviderEgress(id){const provider=cache.providers.find(x=>Number(x.id)===Number(id));if(!provider)return notice('渠道已不存在',true);providerEgressEditId=Number(id);providerEgressBatchIds=[];$('#providerEgressTitle').textContent=provider.name+' · 网络出口';$('#providerEgressSelect').innerHTML=ipPoolOptions(provider.ip_pool_node_id||'');$('#providerEgressSelect').value=provider.ip_pool_node_id?String(provider.ip_pool_node_id):'';$('#providerEgressModal').classList.remove('hidden')}
function openBatchEgress(){const selected=[...authFileSelection];if(!selected.length)return notice('请先勾选认证文件',true);providerEgressEditId=0;providerEgressBatchIds=selected;$('#providerEgressTitle').textContent='批量修改网络出口（'+selected.length+' 份认证文件）';$('#providerEgressSelect').innerHTML=ipPoolOptions('');$('#providerEgressSelect').value='';$('#providerEgressModal').classList.remove('hidden')}
