async function saveProviderEgress(){const batch=providerEgressBatchIds,nodeID=Number($('#providerEgressSelect').value)||0;if(!batch.length&&!providerEgressEditId)return;const button=$('#providerEgressSave'),original=button.textContent;button.disabled=true;button.textContent='保存中…';try{if(batch.length){const d=await api('/api/admin/providers/batch',{method:'POST',body:JSON.stringify({provider_ids:batch,action:'egress',ip_pool_node_id:nodeID})});authFileSelection.clear();closeProviderEgress();notice('已批量更新 '+d.affected+' 份认证文件的网络出口')}else{await api('/api/admin/providers/'+providerEgressEditId,{method:'PATCH',body:JSON.stringify({ip_pool_node_id:nodeID})});closeProviderEgress();notice(nodeID?'渠道已绑定 IP 节点':'渠道已恢复本机直连')}await load()}catch(e){notice('保存出口失败：'+e.message,true)}finally{button.disabled=false;button.textContent=original}}
function providerEgressMeta(x){return '<div class="egress-meta">'+(x.ip_pool_node_id?badge('出口 '+x.ip_pool_node_name,'blue'):badge('本机直连','neutral'))+'</div>'}
function notice(text,bad=false){const x=$('#notice');x.classList.toggle('bad',bad);x.querySelector('use').setAttribute('href',bad?'#i-alert':'#i-check');x.querySelector('span').textContent=text;x.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>x.classList.add('hidden'),3600)}
async function copyText(text){try{await navigator.clipboard.writeText(text);notice('已复制到剪贴板')}catch(e){notice('复制失败，请手动复制',true)}}
async function api(path,options={}){options.headers={...(options.headers||{}),'Content-Type':'application/json'};if(options.method&&options.method!=='GET')options.headers['X-CSRF-Token']=csrf;const r=await fetch(path,options);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error?.message||'请求失败');return d}
function downloadFilename(response,fallback){const value=response.headers.get('Content-Disposition')||'',match=value.match(/filename=\"?([^\";]+)\"?/i);return match?.[1]||fallback}
async function exportProviderBackup(){if(!confirm('导出文件包含所有 API 渠道的明文 Key。请只保存在可信设备中，确认继续导出？'))return;try{const r=await fetch('/api/admin/providers/export',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:'{}'});if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.error?.message||'导出失败')}const blob=await r.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=downloadFilename(r,'fusiongate-providers.json');document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('渠道已导出；文件包含明文 API Key，请妥善保管')}catch(e){notice(e.message,true)}}
function chooseProviderBackup(){const input=$('#providerBackupFile');input.value='';input.click()}
async function importProviderBackup(input){const file=input.files?.[0];if(!file)return;try{const text=await file.text(),backup=JSON.parse(text);if(backup.format!=='fusiongate-provider-backup')throw Error('不是 FusionGate 渠道备份文件');const count=Array.isArray(backup.providers)?backup.providers.length:0;if(!count)throw Error('备份文件中没有渠道');if(!confirm('将导入 '+count+' 个 API 渠道。已存在的同名渠道会更新，Key 和模型映射会去重合并；备份中的 Key 将加密存储。确认继续？'))return;const r=await fetch('/api/admin/providers/import',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:text});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error?.message||'导入失败');await load();let message='导入完成：新增渠道 '+d.providers_created+'，更新 '+d.providers_updated+'，新增 Key '+d.keys_created+'，更新 Key '+d.keys_updated+'，新增模型 '+d.routes_created+'，更新模型 '+d.routes_updated;if(d.warnings?.length)message+='；'+d.warnings.join('；');notice(message,!!d.warnings?.length)}catch(e){notice('渠道导入失败：'+e.message,true)}finally{input.value=''}}
function statCard(label,value,iconId,tone,foot){return '<div class="stat-card" style="--tone:'+tone+';--tone-bg:'+tone+'18"><div class="stat-top"><span>'+label+'</span><span class="stat-icon">'+icon(iconId)+'</span></div><div class="stat-value">'+value+'</div><div class="stat-foot">'+foot+'</div></div>'}
