function healthPickerRoutes(){const provider=cache.providers.find(x=>Number(x.id)===Number(healthPicker.providerId));if(provider?.health_check_enabled===false)return [];return cache.routes.filter(x=>Number(x.provider_id)===Number(healthPicker.providerId)&&x.enabled!==false&&x.provider_enabled!==false&&String(x.capabilities||'').includes('chat'))}

