const openHealthPickerAll=openHealthPicker;openHealthPicker=function(providerId=0){if(Number(providerId)>0)return openHealthPickerAll(providerId);const first=cache.providers.find(x=>x.auth_kind!=='oauth'&&x.enabled&&x.health_check_enabled!==false&&cache.routes.some(r=>Number(r.provider_id)===Number(x.id)&&r.enabled!==false&&String(r.capabilities||'').includes('chat')));if(!first)return notice('没有可检活的 API 渠道模型',true);openHealthPickerAll();const select=$('#healthPickerProvider');[...select.options].forEach(option=>{const provider=cache.providers.find(x=>Number(x.id)===Number(option.value));if(provider?.auth_kind==='oauth')option.remove()});healthPicker.providerId=Number(select.value);healthPicker.selected=new Set(healthPickerRoutes().map(x=>Number(x.id)));renderHealthPickerModels()}
function closeHealthPicker(){$('#healthPickerModal').classList.add('hidden');$('#healthPickerSelection').classList.remove('hidden');$('#healthPickerHealthPanel').classList.add('hidden');healthPicker={providerId:0,locked:false,selected:new Set(),mode:'selection'}}
const openHealthPickerGuarded=openHealthPicker;openHealthPicker=function(providerId=0){const provider=cache.providers.find(x=>Number(x.id)===Number(providerId));if(Number(providerId)>0&&provider?.health_check_enabled===false)return notice('该渠道已禁止检活',true);return openHealthPickerGuarded(providerId)};

