function renderHealthPickerModels(){const routes=visibleHealthPickerRoutes(),all=healthPickerRoutes(),root=$('#healthPickerModels');root.innerHTML=routes.length?routes.map(x=>{const checked=healthPicker.selected.has(Number(x.id)),meta=healthCheckStatusMeta(x.last_health_check_at?x.health_check_status:'pending'),detail=x.last_health_check_at?new Date(x.last_health_check_at).toLocaleString('zh-CN',{hour12:false}):'尚未检活';return '<label class="health-picker-item"><input type="checkbox" '+(checked?'checked':'')+' onchange="toggleHealthPickerRoute('+x.id+',this.checked)"><span><strong>'+esc(x.public_name)+'</strong><small>'+esc(x.upstream_model)+' · '+esc(detail)+'</small></span>'+badge(meta[0],meta[1])+'</label>'}).join(''):'<div class="health-picker-empty">'+(all.length?'没有匹配的模型':'该渠道没有启用的聊天模型')+'</div>';$('#healthPickerCount').textContent='已选择 '+healthPicker.selected.size+' / '+all.length+' 个模型';$('#healthPickerStart').disabled=healthPicker.selected.size===0||!!(healthCheckTask.job&&['queued','running','cancelling'].includes(healthCheckTask.job.status))}
