function tokenDetails(x){if(x.running)return '<span class="token-total">等待统计</span><div class="muted token-breakdown">请求完成后读取上游 usage</div>';if(!x.usage_reported)return '<span class="token-total coverage-warn">未采集</span><div class="muted token-breakdown">上游未返回 usage，费用无法估算</div>';const input=Number(x.input_tokens)||0,parts=['总计 '+formatToken(x.total_tokens),'输入 '+formatToken(input),'输出 '+formatToken(x.output_tokens)];if(Number(x.cached_tokens))parts.push('缓存 '+formatToken(x.cached_tokens));if(Number(x.reasoning_tokens))parts.push('推理 '+formatToken(x.reasoning_tokens));parts.push((x.cost_type==='unknown'?'未定价':formatCost(x.cost_micros)));const warning=input>=40000?badge('超大上下文','red'):input>=20000?badge('大上下文','orange'):'';return '<span class="token-total">'+parts.shift()+'</span>'+warning+'<div class="muted token-breakdown">'+parts.join(' · ')+'</div>'}
function requestReasonLabel(reason){return ({upstream_no_output:'上游没有有效输出',upstream_output_timeout:'等待有效输出超时',upstream_stalled:'上游长时间无有效进度',upstream_empty_stream:'上游返回空流',upstream_stream_interrupted:'上游流中断',upstream_timeout:'上游请求超时',upstream_connection_error:'上游连接失败',upstream_server_error:'上游服务异常',upstream_auth_error:'上游鉴权失败',rate_limited:'上游限流',downstream_canceled:'客户端已取消',downstream_write_error:'写入客户端失败'})[reason]||reason||''}
function providerHealthBadge(x){if(!x.enabled)return badge('已关闭','neutral');if(x.status==='healthy')return badge('健康','green',true);if(x.status==='circuit_open')return providerCircuitCooling(x)?badge('熔断冷却','red'):badge('恢复探测','orange');if(x.status==='auth_expired')return badge('凭据失效','red');if(x.status==='rate_limited')return badge('受限','orange');if(x.status==='degraded')return badge('不稳定','orange');return badge('待检测','neutral')}
function realHealthBadge(x){if(!x)return '';const status=x.health_check_status||'pending',meta=healthCheckStatusMeta(status);return badge(meta[0],meta[1])}
function realHealthDetail(x){if(!x)return '';if(x.health_check_enabled===false)return '已禁止后台与手动检活';if(x.health_check_error)return x.health_check_error;if(!x.last_health_check_at)return '尚未检活';const parts=[];if(x.health_check_mode)parts.push(x.health_check_mode==='connectivity'?'后台连通性':'真实生成');if(Number(x.health_check_model_count)>0)parts.push(Number(x.health_check_model_count)+' 个模型');if(Number(x.health_check_latency_ms)>0)parts.push(Number(x.health_check_latency_ms)+' ms');return parts.join(' · ')||'已记录'}
function healthCheckStatusMeta(status){return ({pending:['待检活','neutral'],queued:['等待','neutral'],running:['检测中','blue'],reachable:['可连接','blue'],healthy:['可用','green'],disabled:['已禁止','neutral'],auth_expired:['凭据失效','red'],rate_limited:['上游限流','orange'],timeout:['超时','orange'],network_error:['网络错误','orange'],server_error:['上游异常','orange'],config_error:['配置错误','red'],invalid_response:['响应异常','red'],content_mismatch:['内容不符','red'],unsupported:['不支持','neutral'],skipped:['已跳过','neutral'],cancelled:['已取消','neutral']})[status]||[status||'未知','neutral']}
function renderHealthPickerJob(job){const panel=$('#healthPickerHealthPanel');if(!panel||healthPicker.mode!=='results'||!job)return;const results=Array.isArray(job.results)?job.results:[],terminal=['completed','cancelled'].includes(job.status),pct=job.total?Math.round(job.completed/job.total*100):0;panel.querySelector('[data-picker-health-title]').textContent=(job.status==='cancelled'?'检活已取消':terminal?'模型检活完成':'正在检活模型')+' · '+job.completed+' / '+job.total;panel.querySelector('[data-picker-health-summary]').innerHTML=badge(job.healthy+' 可用','green')+badge(job.failed+' 异常',job.failed?'red':'neutral')+(job.skipped?badge(job.skipped+' 跳过','neutral'):'');panel.querySelector('[data-picker-health-progress]').style.width=pct+'%';const cancel=panel.querySelector('[data-picker-health-cancel]');cancel.classList.toggle('hidden',!job.can_cancel);cancel.disabled=job.status==='cancelling';cancel.textContent=job.status==='cancelling'?'正在取消…':'取消任务';panel.querySelector('[data-picker-health-results]').innerHTML=results.filter(x=>x.status!=='queued').map(x=>{const meta=healthCheckStatusMeta(x.status),name=(x.public_name||x.model||'模型')+' · '+x.provider_name,detail=x.error||((x.model||'')+(x.first_byte_ms?' · 首字节 '+x.first_byte_ms+' ms':'')+(x.latency_ms?' · 总计 '+x.latency_ms+' ms':''));return '<div class="health-check-result"><strong title="'+esc(name)+'">'+esc(name)+'</strong>'+badge(meta[0],meta[1])+'<small title="'+esc(detail)+'">'+esc(detail||'—')+'</small></div>'}).join('')||'<div class="muted">任务已创建，正在安全排队…</div>'}
function renderModelHealthCheckJob(job){renderHealthPickerJob(job);const results=Array.isArray(job?.results)?job.results:[],providerIDs=new Set(results.map(x=>Number(x.provider_id))),authOnly=providerIDs.size>0&&[...providerIDs].every(id=>cache.providers.find(x=>Number(x.id)===id)?.auth_kind==='oauth'),panel=$(authOnly?'#authHealthCheckPanel':'#providerHealthCheckPanel'),terminal=['completed','cancelled'].includes(job?.status);['#authHealthCheckPanel','#providerHealthCheckPanel'].forEach(id=>$(id)?.classList.toggle('hidden',$(id)!==panel||terminal));if(!panel||!job||terminal||!results.some(x=>Number(x.route_id)>0))return;panel.classList.remove('hidden');const pct=job.total?Math.round(job.completed/job.total*100):0;panel.querySelector('[data-health-title]').textContent='正在检活模型 · '+job.completed+' / '+job.total;panel.querySelector('[data-health-summary]').innerHTML=badge(job.healthy+' 可用','green')+badge(job.failed+' 异常',job.failed?'red':'neutral')+(job.skipped?badge(job.skipped+' 跳过','neutral'):'');panel.querySelector('[data-health-progress]').style.width=pct+'%';const cancel=panel.querySelector('[data-health-cancel]');cancel.classList.toggle('hidden',!job.can_cancel);cancel.disabled=job.status==='cancelling';cancel.textContent=job.status==='cancelling'?'正在取消…':'取消任务';panel.querySelector('[data-health-results]').innerHTML=results.filter(x=>x.status!=='queued').map(x=>{const meta=healthCheckStatusMeta(x.status),name=(x.public_name||x.model||'模型')+' · '+x.provider_name,detail=x.error||((x.model||'')+(x.first_byte_ms?' · 首字节 '+x.first_byte_ms+' ms':'')+(x.latency_ms?' · 总计 '+x.latency_ms+' ms':''));return '<div class="health-check-result"><strong title="'+esc(name)+'">'+esc(name)+'</strong>'+badge(meta[0],meta[1])+'<small title="'+esc(detail)+'">'+esc(detail||'—')+'</small></div>'}).join('')||'<div class="muted">任务已创建，正在安全排队…</div>';updateModelSelectionToolbar()}
function scheduleHealthCheckPoll(delay=700){clearTimeout(healthCheckTask.pollTimer);if(!healthCheckTask.id)return;healthCheckTask.pollTimer=setTimeout(pollHealthCheckJob,delay)}
async function pollHealthCheckJob(){if(!healthCheckTask.id)return;try{const job=await api('/api/admin/health-checks/'+healthCheckTask.id);healthCheckTask.job=job;renderModelHealthCheckJob(job);if(['completed','cancelled'].includes(job.status)){healthCheckTask.id='';clearTimeout(healthCheckTask.pollTimer);notice(job.status==='completed'?'检活完成：'+job.healthy+' 可用，'+job.failed+' 异常':'检活任务已取消',job.failed>0);await load();return}scheduleHealthCheckPoll()}catch(e){healthCheckTask.id='';clearTimeout(healthCheckTask.pollTimer);notice('读取检活进度失败：'+e.message,true)}}
async function cancelHealthCheck(){if(!healthCheckTask.id)return;try{const job=await api('/api/admin/health-checks/'+healthCheckTask.id,{method:'DELETE'});renderModelHealthCheckJob(job);scheduleHealthCheckPoll(150)}catch(e){notice('取消检活失败：'+e.message,true)}}
async function resumeActiveHealthCheck(force=false){if(healthCheckTask.loaded&&!force)return;healthCheckTask.loaded=true;if(healthCheckTask.id)return;try{const d=await api('/api/admin/health-checks');if(d.active&&d.job){healthCheckTask.id=d.job.id;healthCheckTask.job=d.job;renderModelHealthCheckJob(d.job);scheduleHealthCheckPoll(150)}}catch(e){if(force)notice('无法恢复检活任务：'+e.message,true)}}
function oauthSourceLabel(source){return ({cliproxy:'JSON 导入',sub2api:'JSON 导入',fusiongate_oauth:'本端授权',json:'JSON 导入'})[source]||source||'OAuth'}
function providerTypeLabel(type){return ({openai:'OpenAI 官方',openai_compatible:'OpenAI 兼容格式',grok:'xAI 官方',openrouter:'OpenRouter',anthropic:'Anthropic 官方',gemini:'Gemini 官方',codex_oauth:'Codex OAuth',claude_oauth:'Claude OAuth',grok_oauth:'Grok OAuth',gemini_cli:'Gemini CLI'})[type]||type}
