function authPlatformLabel(platform){return ({codex:'OpenAI · Codex',claude:'Anthropic · Claude',grok:'xAI · Grok'})[platform]||platform}
async function fetchProviderBalance(id,force=false){const key=Number(id),cached=providerBalanceCache.get(key);if(!force&&cached?.data&&Date.now()-cached.ts<30000)return cached.data;if(cached?.loading&&cached.promise)return cached.promise;const promise=api('/api/admin/providers/'+id+'/balance'+(force?'?refresh=1':'')).then(data=>{providerBalanceCache.set(key,{data,ts:Date.now(),loading:false});if(data.quota)authQuotaCache.set(key,{ok:true,data:data.quota,ts:Date.now()});return data}).catch(e=>{providerBalanceCache.set(key,{error:e.message||'加载失败',ts:Date.now(),loading:false});return null});providerBalanceCache.set(key,{...(cached||{}),loading:true,promise});return promise}
function providerBalanceStatus(data){if(data.manual){const remaining=Number(data.manual.remaining_micros)||0;return remaining>2000000?['余额充足','green']:remaining>=1000000?['余额预警','yellow']:['余额紧张','red']}if(data.status==='available'){const q=data.quota||{},window=q.primary||q.secondary;if(q.credits_unlimited)return ['上游额度无限','green'];if(q.credits_balance!=null)return ['上游余额 '+q.credits_balance,'green'];if(window)return ['上游剩余 '+formatPercentValue(window.remaining_percent),'green'];return ['上游额度可用','green']}if(data.status==='error')return ['余额读取失败','orange'];return ['未配置余额','gray']}
function cycleReasonLabel(reason){return ({tracking_started:'开始跟踪',manual_balance_added:'添加余额',official_quota_reset:'官方额度重置',reset_card:'使用重置卡'})[reason]||reason||'开始跟踪'}
function renderCycleLine(data){const c=data&&data.cycle;if(!c||!c.started_at)return '';const total=Number(c.requests)||0,priced=Number(c.priced_requests)||0,coverage=total>0?Math.round(priced*100/total)+'%':'—';const start=new Date(c.started_at).toLocaleString('zh-CN',{hour12:false});const title='自 '+esc(start)+' 起 · '+esc(cycleReasonLabel(c.reset_reason))+' · 请求 '+total+' 次 · 计价 '+coverage;return '<div class="provider-balance-line"><small title="'+title+'">本周期累计 <strong>'+formatCost(c.adjusted_micros)+'</strong> · 自 '+esc(start)+' 起</small></div>'}
function renderProviderBalance(x,wide=false){const key=Number(x.id),cached=providerBalanceCache.get(key),settings='<button onclick="openProviderBalanceModal('+key+')">余额设置</button>';if(!cached){fetchProviderBalance(key).then(()=>{renderProviders();renderAuthFiles()});return '<div class="provider-balance gray"><small>正在读取余额与费用…</small></div>'}if(cached.loading)return '<div class="provider-balance gray"><small>正在刷新…</small></div>';if(cached.error)return '<div class="provider-balance gray"><div class="provider-balance-line">'+badge('读取失败','orange')+'<button onclick="refreshProviderBalance('+key+',this)">重试</button></div><small>'+esc(cached.error)+'</small></div>';const data=cached.data||{},state=providerBalanceStatus(data),manual=data.manual,spend=data.estimated_spend||{},coverage=Number(spend.cost_coverage)||0,cycleHtml=renderCycleLine(data);if(manual){const used=Math.max(0,Math.min(100,Number(manual.used_percent)||0)),tone=state[1],baseline=manual.baseline_at?new Date(manual.baseline_at).toLocaleString('zh-CN',{hour12:false}):'—',manualCoverage=Number(manual.cost_coverage)||0;return '<div class="provider-balance '+tone+'"><div class="provider-balance-line"><strong>'+formatCost(manual.remaining_micros)+' 剩余</strong>'+badge(state[0],tone==='yellow'?'orange':tone)+'</div><div class="balance-track" title="100% 代表余额耗尽"><i style="width:'+used+'%"></i></div><div class="balance-caption"><small>已消耗 '+formatPercentValue(used)+'</small><small>初始 '+formatCost(manual.configured_micros)+'</small></div><div class="provider-balance-line"><small title="基线 '+esc(baseline)+'">倍率消费 '+formatCost(manual.adjusted_spend_micros)+' · 计价 '+formatPercent(manualCoverage)+'</small>'+settings+'</div>'+cycleHtml+'</div>'}const detail=state[1]==='gray'?(cycleHtml?'累计已开始跟踪':'输入当前余额后开始跟踪'):formatCost(spend.cost_micros)+' 账本估算';return '<div class="provider-balance '+state[1]+'"><div class="provider-balance-line">'+badge(state[0],state[1]==='yellow'?'orange':state[1])+settings+'</div><div class="balance-track"><i style="width:0"></i></div>'+(cycleHtml||'<small>'+detail+' · 计价 '+formatPercent(coverage)+'</small>')+'</div>'}
async function refreshProviderBalance(id,button){const original=button?.textContent;if(button){button.disabled=true;button.textContent='刷新中…'}try{await fetchProviderBalance(id,true);renderProviders();renderAuthFiles();notice('余额与账本费用已刷新')}catch(e){notice('刷新失败：'+e.message,true)}finally{if(button){button.disabled=false;button.textContent=original||'刷新'}}}
async function fetchAuthQuota(id,force){const key=Number(id);if(!force){const cached=authQuotaCache.get(key);if(cached&&cached.ok&&cached.ts&&Date.now()-cached.ts<30000)return cached.data}try{const data=await api('/api/admin/auth/quota/'+id);authQuotaCache.set(key,{ok:true,data,ts:Date.now()});return data}catch(e){authQuotaCache.set(key,{ok:false,error:e.message||'加载失败',ts:Date.now()});return null}}
function formatPercentValue(value){const n=Number(value);if(!Number.isFinite(n))return '—';return Math.max(0,Math.min(100,n)).toFixed(n%1===0?0:1)+'%'}
function formatResetAt(value){if(!value)return '';try{return new Date(value).toLocaleString('zh-CN',{hour12:false})}catch(e){return String(value)}}
function formatResetCountdown(seconds){const n=Math.max(0,Number(seconds)||0);if(!n)return '';if(n<60)return n+' 秒后';if(n<3600)return Math.ceil(n/60)+' 分钟后';if(n<86400)return (n/3600).toFixed(n%3600===0?0:1)+' 小时后';return (n/86400).toFixed(n%86400===0?0:1)+' 天后'}
function formatWindowDuration(seconds){const n=Math.max(0,Number(seconds)||0);if(!n)return '—';if(n>=500000)return '7 天';if(n>=10000&&n<=30000)return '5 小时';if(n%86400===0)return (n/86400)+' 天';if(n%3600===0)return (n/3600)+' 小时';if(n%60===0)return (n/60)+' 分钟';return n+' 秒'}
function quotaWindowName(window,fallback){const sec=Number(window&&window.limit_window_seconds)||0;if(sec>=500000)return '周额度';if(sec>=10000&&sec<=30000)return '5 小时额度';if(sec>0&&sec<10000)return '短时额度';return fallback||'额度窗口'}
function quotaBarTone(used){const n=Number(used)||0;if(n>=90)return 'danger';if(n>=70)return 'warn';return ''}
function renderQuotaWindowCard(window,fallbackName){if(!window)return '';const used=Math.max(0,Math.min(100,Number(window.used_percent)||0));const remaining=Math.max(0,Math.min(100,Number(window.remaining_percent??(100-used))||0));const name=quotaWindowName(window,fallbackName);const resetText=formatResetAt(window.reset_at)||'—';const countdown=formatResetCountdown(window.reset_after_seconds)||'—';const duration=formatWindowDuration(window.limit_window_seconds);return '<div class="auth-quota-window"><header><span>'+esc(name)+'</span><strong>'+esc(formatPercentValue(remaining))+' 剩余</strong></header><div class="auth-quota-bar '+quotaBarTone(used)+'"><i style="width:'+used+'%"></i></div><div class="auth-quota-rows"><div><span>已用</span><strong>'+esc(formatPercentValue(used))+'</strong></div><div><span>窗口时长</span><strong>'+esc(duration)+'</strong></div><div><span>重置倒计时</span><strong>'+esc(countdown)+'</strong></div><div><span>重置时间</span><strong title="'+esc(resetText)+'">'+esc(resetText)+'</strong></div></div></div>'}
function availableResetCards(quota){const cards=Array.isArray(quota&&quota.reset_card_details)?quota.reset_card_details:[];return cards.filter(c=>{const status=String(c.status||'available').toLowerCase();return !status||status==='available'})}
function nextResetCardExpiry(quota){const cards=availableResetCards(quota).slice().sort((a,b)=>String(a.expires_at||'').localeCompare(String(b.expires_at||'')));const first=cards[0];return first?formatResetAt(first.expires_at):''}
async function refreshAuthQuota(id,button){const original=button?.innerHTML;if(button){button.disabled=true;button.textContent='刷新中…'}try{await fetchAuthQuota(id,true);renderAuthFiles();notice('额度已刷新')}catch(e){notice('刷新额度失败：'+e.message,true)}finally{if(button){button.disabled=false;button.innerHTML=original||'刷新额度'}}}
async function redeemAuthResetCard(id,button){const cached=authQuotaCache.get(Number(id));const quota=cached&&cached.ok?cached.data:null;const count=Number(quota&&quota.reset_cards)||0;if(count<=0){notice('这不是装饰按钮：需要 OpenAI 赠送的重置卡。当前账号可用重置卡为 0，无法核销。可先点“刷新”再试。',true);return}if(!confirm('确认使用 1 张重置卡？\n\n这会调用 OpenAI 官方接口立刻重置该 Codex 账号的额度窗口，且不可撤销。'))return;const original=button?.innerHTML;if(button){button.disabled=true;button.textContent='重置中…'}try{const result=await api('/api/admin/auth/quota/'+id+'/reset',{method:'POST',body:JSON.stringify({})});if(result&&result.quota)authQuotaCache.set(Number(id),{ok:true,data:result.quota,ts:Date.now()});else await fetchAuthQuota(id,true);renderAuthFiles();const left=Number(result?.quota?.reset_cards);notice('重置卡已核销'+(Number.isFinite(left)?'，剩余 '+left+' 张':'')+'，额度已刷新')}catch(e){notice('使用重置卡失败：'+e.message,true)}finally{if(button){button.disabled=false;button.innerHTML=original||'使用重置卡'}}}
function renderQuotaInfo(x,providerId){const platform=authPlatform(x);if(platform!=='codex')return '';const cached=authQuotaCache.get(Number(providerId));if(!cached){fetchAuthQuota(providerId).then(()=>renderAuthFiles());return '<div class="auth-quota-panel"><div class="auth-quota-empty">正在加载 Codex 额度与重置卡…</div></div>'}if(!cached.ok){return '<div class="auth-quota-panel"><div class="auth-quota-head"><strong>Codex 额度</strong><button class="btn btn-secondary btn-sm" type="button" onclick="refreshAuthQuota('+providerId+',this)">重试</button></div><div class="auth-quota-empty" title="'+esc(cached.error||'加载失败')+'">额度获取失败：'+esc(cached.error||'未知错误')+'</div></div>'}const quota=cached.data||{};const primary=quota.primary||null;const secondary=quota.secondary||null;const resetCards=Number(quota.reset_cards)||0;const plan=quota.plan_type||quota.subscription_plan||'unknown';const allowed=quota.allowed!==false;const limitReached=!!quota.limit_reached;const credits=quota.credits_unlimited?'无限':(quota.credits_balance==null?'—':String(quota.credits_balance));const expiry=nextResetCardExpiry(quota);const statusText=limitReached?'已触达限额':(allowed?'可用':'受限');const statusTone=limitReached?'red':(allowed?'green':'orange');const windows=[renderQuotaWindowCard(primary,'主额度'),renderQuotaWindowCard(secondary,'次额度')].filter(Boolean).join('');const windowsHtml=windows||'<div class="auth-quota-empty">上游未返回窗口明细</div>';const resetTitle=availableResetCards(quota).map(c=>(c.status||'available')+(c.expires_at?' · 到期 '+formatResetAt(c.expires_at):'')).join('\n')||(resetCards+' 张可用');return '<div class="auth-quota-panel"><div class="auth-quota-head"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><strong>Codex 额度</strong>'+badge(String(plan),'blue')+badge(statusText,statusTone)+'</div><button class="btn btn-ghost btn-sm" type="button" onclick="refreshAuthQuota('+providerId+',this)">刷新额度</button></div><div class="auth-quota-grid">'+windowsHtml+'</div><div class="auth-quota-rows" style="grid-template-columns:1fr 1fr;display:grid;gap:6px 12px"><div><span>购买积分</span><strong>'+esc(credits)+'</strong></div><div><span>限额状态</span><strong>'+esc(limitReached?'已达上限':'未达上限')+'</strong></div></div><div class="auth-quota-reset"><div class="reset-copy"><span>GPT 赠送重置卡</span><strong title="'+esc(resetTitle)+'">'+resetCards+' 张可用'+(resetCards>0?(expiry?' · 最近到期 '+expiry:''):' · 需 OpenAI 赠送后才能核销')+'</strong></div><div style="display:flex;gap:7px;flex-wrap:wrap"><button class="btn btn-secondary btn-sm" type="button" onclick="refreshAuthQuota('+providerId+',this)">刷新</button><button class="btn '+(resetCards>0?'btn-primary':'btn-secondary')+' btn-sm" type="button" title="'+(resetCards>0?'使用 1 张 GPT 赠送重置卡，立刻重置额度窗口':'当前 0 张重置卡，点击可查看说明')+'" onclick="redeemAuthResetCard('+providerId+',this)">'+ (resetCards>0?'使用重置卡':'无卡可重置') +'</button></div></div></div>'}
function externalAuthSource(source){return ['cliproxy','cli-proxy','cli_proxy','cpa','sub2api'].includes(String(source||'').toLowerCase())}
function authCredentialExpired(x){const expires=x.auth_expires_at?new Date(x.auth_expires_at).getTime():NaN;return x.auth_status==='expired'||x.auth_status==='refresh_failed'||(Number.isFinite(expires)&&expires<=Date.now()&&(externalAuthSource(x.auth_source)||!x.has_refresh_token))}
function authState(x){const err=String(x.last_error||x.health_check_error||'').toLowerCase();const src=String(x.auth_source||'');const external=externalAuthSource(src);const native=src==='fusiongate_oauth';const revoked=err.includes('revoked')||err.includes('invalid_grant')||err.includes('invalid refresh');const expired=authCredentialExpired(x);if(revoked)return ['Refresh 已吊销','red'];if(expired)return external?['等待凭据更新','orange']:['续期失败','red'];if(external)return ['外部导入凭据','blue'];if(native||x.has_refresh_token)return ['本端自动续期','green'];return ['到期需重登','orange']}
function authErrorBanner(x){const msg=String(x.last_error||x.health_check_error||'').trim();if(!msg)return '';const revoked=/revoked|invalid_grant|invalid refresh/i.test(msg);const tip=revoked?'xAI/OpenAI 已吊销该 Refresh Token，自动续期无法恢复，需要重新导入/重新授权。':'自动续期失败详情';return '<div class="auth-error-banner'+(revoked?' revoked':'')+'" title="'+esc(msg)+'"><strong>'+esc(tip)+'</strong><span>'+esc(msg)+'</span></div>'}
function visibleAuthFiles(){const all=cache.providers.filter(x=>x.auth_kind==='oauth'&&authPlatform(x));return authFileVendor==='all'?all:all.filter(x=>authPlatform(x)===authFileVendor)}
function queueMissingAuthModelSync(){if(authModelSyncQueued||!$('#page-authfiles')?.classList.contains('active'))return;const ids=cache.providers.filter(x=>x.auth_kind==='oauth'&&authPlatform(x)&&!authCredentialExpired(x)&&Number(x.model_count||0)===0&&!authModelSyncAttempted.has(Number(x.id))).map(x=>Number(x.id));if(!ids.length)return;authModelSyncQueued=true;setTimeout(async()=>{try{await syncMissingAuthModels(ids)}finally{authModelSyncQueued=false}},0)}
async function syncMissingAuthModels(ids){const targets=ids.filter(id=>!authModelSyncAttempted.has(id));if(!targets.length)return;targets.forEach(id=>{authModelSyncAttempted.add(id);authModelSyncing.add(id)});renderAuthFiles();let processed=0,added=0,failed=0;try{for(let offset=0;offset<targets.length;offset+=4){const batch=targets.slice(offset,offset+4),d=await api('/api/admin/auth/models/sync',{method:'POST',body:JSON.stringify({provider_ids:batch})});processed+=batch.length;added+=Number(d.added||0);failed+=Number(d.failed||0);(d.items||[]).forEach(item=>{const provider=cache.providers.find(x=>Number(x.id)===Number(item.id));if(provider&&item.status==='ok')provider.model_count=Math.max(Number(provider.model_count||0),Number(item.added||0)+Number(item.existing||0))});batch.forEach(id=>authModelSyncing.delete(id));renderAuthFiles();if(processed<targets.length)notice('正在自动识别认证模型 '+processed+' / '+targets.length+'…')}notice('认证模型自动识别完成：处理 '+processed+' 份，新增模型 '+added+'，失败 '+failed,failed>0);await load()}catch(e){notice('认证模型自动识别中断：已处理 '+processed+' / '+targets.length+'，'+e.message,true)}finally{targets.forEach(id=>authModelSyncing.delete(id));renderAuthFiles()}}
function setAuthFileVendor(vendor){authFileVendor=vendor;renderAuthFiles()}
function updateAuthExportButton(){const count=authFileSelection.size,active=count>0,countEl=$('#authSelectionCount');if(countEl)countEl.textContent=active?'已选 '+count+' 份':'未选择';const exportButton=$('#authExportButton');if(exportButton){exportButton.textContent='导出所选（'+count+'）';exportButton.disabled=!active}['authBatchEnableButton','authBatchDisableButton','authBatchDeleteButton','authBatchModelsButton','authBatchEgressButton'].forEach(id=>{const button=$('#'+id);if(button)button.disabled=!active})}
function ensureAuthBatchHealthButton(){const enable=$('#authBatchEnableButton');if(!enable)return;let button=$('#authBatchHealthButton');if(!button){enable.insertAdjacentHTML('beforebegin','<button id="authBatchHealthButton" class="btn btn-secondary btn-sm" type="button" onclick="batchHealthAuthFiles()" disabled>'+icon('i-activity')+'批量检活</button>');button=$('#authBatchHealthButton')}button.disabled=authFileSelection.size===0}
function batchHealthAuthFiles(){const selected=[...authFileSelection],routes=cache.routes.filter(x=>selected.includes(Number(x.provider_id))&&cache.providers.find(p=>Number(p.id)===Number(x.provider_id))?.health_check_enabled!==false&&x.enabled!==false&&x.provider_enabled!==false&&String(x.capabilities||'').includes('chat'));if(!selected.length)return notice('请先勾选认证文件',true);if(!routes.length)return notice('所选认证文件没有可检活的启用聊天模型',true);return startModelHealthCheck(routes,'selected')}
const updateAuthExportButtonBase=updateAuthExportButton;updateAuthExportButton=function(){updateAuthExportButtonBase();ensureAuthBatchHealthButton()}
