function selectVisibleAuthFiles(selected){if(selected)visibleAuthFiles().forEach(x=>authFileSelection.add(Number(x.id)));else authFileSelection.clear();renderAuthFiles()}
function authRuntimeBadges(x){const failures=Math.max(0,Number(x.consecutive_failures)||0);const runtime=!x.enabled&&failures>=5?badge('已自动暂停','red'):!x.enabled?badge('已暂停','neutral'):providerHealthBadge(x);return runtime+badge('连续失败 '+failures+' / 5',failures?'orange':'neutral')}
function renderAuthFiles(){const root=$('#authFiles');if(!root)return;renderRoutingStrategy();$$('.auth-filter').forEach(x=>x.classList.toggle('active',x.dataset.vendor===authFileVendor));const all=cache.providers.filter(x=>x.auth_kind==='oauth'&&authPlatform(x));const valid=new Set(all.map(x=>Number(x.id)));authFileSelection.forEach(id=>{if(!valid.has(id))authFileSelection.delete(id)});const files=visibleAuthFiles();$('#authFileCount').textContent=all.length+' 份';updateAuthExportButton();if(!files.length){root.innerHTML=emptyRow(1,'i-lock','还没有认证文件','通过官方授权或兼容 OAuth JSON 添加账号；导入时默认不勾选任何凭据。','<div class="page-actions"><button class="btn btn-primary" onclick="openAuthAccess()">'+icon('i-lock')+'添加认证文件</button></div>');return}const groups=new Map();files.forEach(p=>{const key=p.base_url||'__unknown__';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)});const sortByHealth=arr=>arr.sort((a,b)=>(b.health_score||0)-(a.health_score||0)||(b.priority-a.priority)||(a.id-b.id));[...groups.values()].forEach(sortByHealth);const entries=[...groups.entries()].sort((a,b)=>{const countDiff=b[1].length-a[1].length;if(countDiff!==0)return countDiff;return a[0].localeCompare(b[0])});root.innerHTML=entries.map(([baseUrl,providers])=>{const collapsed=collapsedGroups.has(baseUrl);const healthCount=providers.filter(x=>x.health_check_status==='healthy').length;const platforms=[...new Set(providers.map(p=>authPlatform(p)).filter(Boolean))];const accent=platformColor(platforms[0]||'');return '<section class="auth-vendor-group"><div class="auth-vendor-head group-head" onclick="toggleGroupCollapse(this.dataset.key)" data-key="'+esc(baseUrl)+'" style="--group-accent:'+accent+'"><div><h2>'+icon(collapsed?'i-chevron-right':'i-chevron-down')+esc(groupLabel(baseUrl,providers))+'</h2><span class="muted">'+providers.length+' 份</span></div><div class="group-hint">'+(healthCount>0?badge(healthCount+' 健康','green',true):'')+'</div></div>'+(collapsed?'':'<div class="auth-file-grid">'+providers.map(renderAuthCard).join('')+'</div>')+'</section>'}).join('');queueMissingAuthModelSync()}
function groupLabel(baseUrl,providers){const names=[...new Set(providers.map(p=>authPlatformLabel(authPlatform(p))))];return names.join(' / ')||'未分类'}
