const renderAuthCardHealthBase=renderAuthCard;renderAuthCard=function(x){return renderAuthCardHealthBase(x).replace('<strong>最近检活</strong>','<strong>最近检活</strong><label class="channel-switch"><input type="checkbox" '+(x.health_check_enabled!==false?'checked':'')+' onchange="toggleProviderHealthCheck('+x.id+',this.checked,this)"><span class="switch-track"><span></span></span><strong>允许检活</strong></label>')};

async function batchAuthFiles(action){const selected=[...authFileSelection];if(!selected.length)return notice('请先勾选认证文件',true);const labels={enable:'启动',disable:'暂停',delete:'删除'},label=labels[action];if(!label)return;if(action==='delete'&&!confirm('将永久删除所选 '+selected.length+' 份认证文件及其关联模型路由，无法恢复。\n\n确认继续？'))return;const button=$('#'+({enable:'authBatchEnableButton',disable:'authBatchDisableButton',delete:'authBatchDeleteButton'})[action]),original=button?.textContent;if(button){button.disabled=true;button.textContent='处理中…'}try{const d=await api('/api/admin/providers/batch',{method:'POST',body:JSON.stringify({provider_ids:selected,action})});authFileSelection.clear();notice('已批量'+label+' '+d.affected+' 份认证文件');await load()}catch(e){notice('批量'+label+'失败：'+e.message,true)}finally{if(button&&original)button.textContent=original;updateAuthExportButton()}}
function exportFilename(response,isZip=false){const value=response.headers.get('Content-Disposition')||'';const encoded=value.match(/filename\*=UTF-8''([^;]+)/i);if(encoded){try{return decodeURIComponent(encoded[1]).replace(/[\\/:*?"<>|]/g,'-')}catch(e){}}const plain=value.match(/filename="?([^";]+)"?/i);return (plain?.[1]||('fusiongate-auth-export-'+new Date().toISOString().slice(0,10)+(isZip?'.zip':'.json'))).replace(/[\\/:*?"<>|]/g,'-')}
async function exportSelectedAuthFiles(){const selected=[...authFileSelection];if(!selected.length)return notice('请先勾选要导出的认证文件',true);const single=selected.length===1;if(!confirm('导出文件包含 Access Token、Refresh Token 和 ID Token 等敏感凭据。请勿上传到公共仓库，并在迁移完成后妥善保管或删除本地副本。\n\n'+(single?'确认导出所选认证文件？':'确认导出所选 '+selected.length+' 份认证文件？每个账号会生成一个独立 JSON 文件，并打包为 ZIP 下载。')))return;const button=$('#authExportButton'),original=button.textContent;button.disabled=true;button.textContent='正在加密读取…';const sink=window.open('about:blank','_blank');try{const response=await fetch('/api/admin/auth/export',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({provider_ids:selected,acknowledge_sensitive_export:true})});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.error?.message||'导出失败')}const isZip=(response.headers.get('Content-Type')||'').includes('zip');const blob=new Blob([await response.arrayBuffer()],{type:isZip?'application/zip':'application/json'});const url=URL.createObjectURL(blob),filename=exportFilename(response,isZip);if(sink&&!sink.closed){sink.document.write('<!doctype html><title>导出认证文件</title><p style="font:14px system-ui">正在下载 <code>'+filename.replace(/[<>&]/g,'')+'</code>…</p>');sink.document.close();sink.location=url;setTimeout(()=>{try{sink.close()}catch(e){}URL.revokeObjectURL(url)},1500)}else{const link=document.createElement('a');link.href=url;link.download=filename;link.rel='noopener';link.style.display='none';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}authFileSelection.clear();renderAuthFiles();notice(single?'已导出 1 个认证文件':'已导出 '+selected.length+' 份认证文件（ZIP 内每个账号一个 JSON）')}catch(e){if(sink&&!sink.closed)sink.close();notice('导出失败：'+e.message,true)}finally{button.disabled=false;updateAuthExportButton()}}
