async function saveProviderOrder(ordinaryIDs){const full=providerOrder(),slots=[];full.forEach((provider,index)=>{if(provider.auth_kind!=='oauth')slots.push(index)});if(slots.length!==ordinaryIDs.length)return notice('渠道列表已变化，请刷新后重试',true);ordinaryIDs.forEach((id,index)=>{full[slots[index]]=cache.providers.find(x=>Number(x.id)===Number(id))});const ids=full.map(x=>Number(x.id));try{await api('/api/admin/providers/reorder',{method:'PATCH',body:JSON.stringify({provider_ids:ids})});ids.forEach((id,index)=>{const provider=cache.providers.find(x=>Number(x.id)===id);if(provider)provider.sort_order=index});renderProviders();renderRoutes();notice('上游渠道位置已更新')}catch(e){notice('更新渠道位置失败：'+e.message,true);await load()}}
