const renderProvidersBase=renderProviders;renderProviders=function(){renderProvidersBase();$$('#providers button[onclick^="openProviderEdit("]').forEach(button=>{button.innerHTML=icon('i-edit')+'渠道设置';button.title='连接信息、Key 管理、运行设置'});$$('#providers button[onclick^="discoverModels("]').forEach(button=>{button.innerHTML=icon('i-refresh')+'识别模型';button.title='使用全部启用 Key 识别并合并模型'});$$('#providers button[onclick^="resetHealth("]').forEach(button=>{const match=button.getAttribute('onclick').match(/\d+/);if(!match)return;button.setAttribute('onclick','openHealthPicker('+match[0]+')');button.className='btn btn-secondary';button.innerHTML=icon('i-activity')+'检活'});decorateProviderOrder()}
