async function startOAuth(platform,button){clearTimeout(authAccess.pollTimer);const popup=window.open('about:blank','_blank');const original=button.textContent;button.disabled=true;button.textContent='正在准备…';try{const d=await api('/api/admin/auth/oauth/start',{method:'POST',body:JSON.stringify({platform})});authAccess.sessionId=d.session_id;authAccess.platform=d.platform;authAccess.flow=d.flow||'callback';authAccess.authURL=d.verification_url_complete||d.verification_url||d.auth_url;$('#oauthCompletion').classList.remove('hidden');const device=authAccess.flow==='device';$('#oauthStepTitle').textContent=authPlatformLabel(platform)+' · '+(device?'设备授权':'粘贴授权回调');$('#oauthOpenLink').href=authAccess.authURL;$('#oauthOpenLink').textContent=device?'打开 xAI 授权页 ↗':'重新打开授权页 ↗';$('#oauthCallback').value='';$('#oauthCallbackField').classList.toggle('hidden',device);$('#oauthDevice').classList.toggle('hidden',!device);$('#oauthDeviceCode').textContent=device?d.user_code:'—';$('#oauthCompleteButton').innerHTML=icon('i-check')+(device?'检查授权状态':'完成并创建认证文件');if(popup)popup.location.href=authAccess.authURL;else notice('浏览器拦截了新窗口，请点击右侧链接继续授权',true)}catch(e){if(popup)popup.close();notice('无法开始授权：'+e.message,true)}finally{button.disabled=false;button.textContent=original}}
async function completeOAuth(auto=false){const device=authAccess.flow==='device',callback=$('#oauthCallback').value.trim(),priority=Number($('#oauthPriority').value);if(!authAccess.sessionId)return notice('请先选择平台并开始授权',true);if(!device&&!callback)return notice('请粘贴完整回调地址',true);if(!Number.isInteger(priority)||priority<0)return notice('优先级必须是大于等于 0 的整数',true);const button=$('#oauthCompleteButton'),original=button.innerHTML;button.disabled=true;button.textContent=device?'正在检查授权…':'正在验证并保存…';try{const d=await api('/api/admin/auth/oauth/complete',{method:'POST',body:JSON.stringify({session_id:authAccess.sessionId,callback:device?'':callback,name:$('#oauthProviderName').value.trim(),priority})});if(d.pending){const wait=Math.max(2,Number(d.retry_after)||5);if(!auto)notice('尚未完成 xAI 授权，将自动继续检查');clearTimeout(authAccess.pollTimer);authAccess.pollTimer=setTimeout(()=>{if(authAccess.sessionId&&authAccess.flow==='device')completeOAuth(true)},wait*1000);return}authAccess.sessionId='';authAccess.flow='';$('#oauthCallback').value='';closeAuthAccess();notice('已创建认证文件：'+d.name+(d.model_sync?.status==='ok'?'，自动添加 '+d.model_sync.added+' 个模型':'；模型自动识别失败，可稍后重试'),d.model_sync?.status==='error');await load()}catch(e){clearTimeout(authAccess.pollTimer);notice('授权失败：'+e.message,true)}finally{button.disabled=false;button.innerHTML=original}}
async function readCredentialFiles(input){const files=[...(input.files||[])];if(!files.length)return;const perFileLimit=2*1024*1024,totalLimit=8*1024*1024;const oversized=files.find(file=>file.size>perFileLimit);if(oversized){input.value='';return notice('文件 '+oversized.name+' 超过 2 MiB',true)}const total=files.reduce((sum,file)=>sum+file.size,0);if(total>totalLimit){input.value='';return notice('所选 JSON 文件总大小不能超过 8 MiB',true)}try{const parts=await Promise.all(files.map(async file=>{try{return await file.text()}catch(e){throw Error('无法读取 '+file.name)}}));$('#credentialJSON').value=parts.join('\n');authAccess.importSessionId='';authAccess.items=[];authAccess.selected.clear();$('#credentialPreview').classList.add('hidden');$('#credentialImportOptions').classList.add('hidden');notice('已读取 '+files.length+' 个 JSON 文件，请点击“识别凭据”确认内容')}catch(e){notice(e.message,true)}finally{input.value=''}}
function credentialStatusLabel(status){return ({ready:'可用',expired_refreshable:'已过期，可续期',expired:'已过期'})[status]||status||'待检查'}
function credentialStatusTone(status){return status==='expired'?'red':status==='expired_refreshable'?'orange':'green'}
function renderCredentialPreview(){const box=$('#credentialPreview'),items=authAccess.items;box.classList.remove('hidden');const tools=items.length?'<div class="credential-selection-toolbar"><span id="credentialSelectedCount" class="credential-selection-count">已选择 '+authAccess.selected.size+' / '+items.length+'</span><div class="credential-selection-actions"><button class="btn btn-secondary btn-sm" type="button" onclick="selectCredentialImports(true)">全选全部</button><button class="btn btn-ghost btn-sm" type="button" onclick="selectCredentialImports(false)">清空选择</button></div></div>':'';const list=items.length?items.map(x=>'<label class="credential-item"><input type="checkbox" '+(authAccess.selected.has(x.id)?'checked':'')+' onchange="toggleCredentialImport('+x.id+',this.checked)"><span class="credential-main"><strong>'+esc(x.name)+'</strong><small>'+esc(x.email||x.account_id||'未识别账号信息')+(x.expires_at?' · 到期 '+new Date(x.expires_at).toLocaleString('zh-CN',{hour12:false}):'')+'</small></span><span class="credential-tags">'+badge(x.platform==='codex'?'Codex':x.platform==='claude'?'Claude':'Grok','blue')+badge(oauthSourceLabel(x.source),'neutral')+badge(credentialStatusLabel(x.status),credentialStatusTone(x.status))+(x.has_refresh_token?badge('可续期','green'):badge('无刷新令牌','orange'))+(x.duplicate?badge('已存在','orange'):'')+'</span></label>').join(''):'<div class="model-picker-empty">没有识别到可导入的凭据</div>';box.innerHTML=tools+list;updateCredentialImportButton()}
function selectCredentialImports(selected){authAccess.items.forEach(item=>{if(selected)authAccess.selected.add(item.id);else authAccess.selected.delete(item.id)});renderCredentialPreview()}
function toggleCredentialImport(id,checked){checked?authAccess.selected.add(id):authAccess.selected.delete(id);updateCredentialImportButton()}
function updateCredentialImportButton(){const button=$('#credentialImportButton'),count=authAccess.selected.size,total=authAccess.items.length,countEl=$('#credentialSelectedCount');if(countEl)countEl.textContent='已选择 '+count+' / '+total;button.disabled=count===0;button.innerHTML=icon('i-check')+'导入所选（'+count+'）'}
async function previewCredentialImport(){const content=$('#credentialJSON').value.trim();if(!content)return notice('请粘贴或选择凭据 JSON',true);const button=$('#credentialPreviewButton'),original=button.textContent;button.disabled=true;button.textContent='正在识别…';try{const d=await api('/api/admin/auth/import/preview',{method:'POST',body:JSON.stringify({content})});authAccess.importSessionId=d.session_id;authAccess.items=Array.isArray(d.items)?d.items:[];authAccess.selected=new Set();renderCredentialPreview();$('#credentialImportOptions').classList.remove('hidden');notice('已识别 '+authAccess.items.length+' 个账号，请选择要导入的项')}catch(e){authAccess.importSessionId='';authAccess.items=[];authAccess.selected.clear();$('#credentialPreview').classList.add('hidden');$('#credentialImportOptions').classList.add('hidden');notice('识别失败：'+e.message,true)}finally{button.disabled=false;button.textContent=original}}
async function commitCredentialImport(){const selected=[...authAccess.selected],priority=Number($('#importPriority').value);if(!authAccess.importSessionId||!selected.length)return notice('请先识别并勾选账号',true);if(!Number.isInteger(priority)||priority<0)return notice('优先级必须是大于等于 0 的整数',true);const button=$('#credentialImportButton'),original=button.innerHTML;button.disabled=true;button.textContent='正在加密导入…';try{const d=await api('/api/admin/auth/import/commit',{method:'POST',body:JSON.stringify({session_id:authAccess.importSessionId,selected,priority,update_existing:$('#updateExistingCredential').checked})});authAccess.importSessionId='';authAccess.items=[];authAccess.selected.clear();$('#credentialJSON').value='';$('#credentialPreview').classList.add('hidden');$('#credentialImportOptions').classList.add('hidden');closeAuthAccess();notice('导入完成：新增 '+d.created+'，更新 '+d.updated+'，自动添加模型 '+(d.model_sync?.added||0)+(d.model_sync?.failed?'，识别失败 '+d.model_sync.failed:''),Number(d.model_sync?.failed||0)>0);await load()}catch(e){notice('导入失败：'+e.message,true);button.disabled=false;button.innerHTML=original}}
async function toggleProviderHealthCheck(id,enabled,input){if(input)input.disabled=true;try{await api('/api/admin/providers/'+id,{method:'PATCH',body:JSON.stringify({health_check_enabled:enabled})});notice(enabled?'已允许检活':'已禁止检活');await load()}catch(e){notice('更新检活开关失败：'+e.message,true);await load()}finally{if(input)input.disabled=false}}
async function toggleProvider(id,enabled,input){if(input)input.disabled=true;try{await api('/api/admin/providers/'+id,{method:'PATCH',body:JSON.stringify({enabled})});const provider=cache.providers.find(x=>x.id===id);if(provider)provider.enabled=enabled;notice(enabled?'渠道已开启':'渠道已关闭');await load()}catch(e){notice(e.message,true);await load()}finally{if(input)input.disabled=false}}
async function updateProviderPriority(input){const id=Number(input.dataset.id),priority=Number(input.value);if(!Number.isInteger(priority)||priority<0){notice('优先级必须是大于等于 0 的整数',true);return load()}input.disabled=true;try{await api('/api/admin/providers/'+id,{method:'PATCH',body:JSON.stringify({priority})});const provider=cache.providers.find(x=>x.id===id);if(provider)provider.priority=priority;notice('渠道优先级已更新');renderProviders();renderRoutes()}catch(e){notice(e.message,true);await load()}finally{input.disabled=false}}
function providerPriority(id){return cache.providers.find(x=>x.id===id)?.priority??0}
function routeStatus(x){if(!x.enabled)return badge('路由不可用','neutral');if(x.provider_enabled===false)return badge('渠道已关闭','neutral');if(x.provider_status==='circuit_open')return badge('熔断中','red');if(x.provider_status==='auth_expired')return badge('凭据失效','red');if(x.provider_status==='rate_limited')return badge('受限','orange');if(x.provider_status==='degraded')return badge('不稳定','orange');if(x.provider_status==='healthy')return badge('健康','green',true);return badge('待观测','neutral')}
function routeHasPrice(x){return ['input_price_micros','cached_price_micros','output_price_micros','long_input_price_micros','long_cached_price_micros','long_output_price_micros'].some(key=>Number(x[key])>0)}
function priceRange(rows,key){const values=rows.map(x=>Number(x[key])||0).filter(x=>x>0);if(!values.length)return '未定价';const min=Math.min(...values),max=Math.max(...values);return min===max?formatPrice(min):formatCost(min)+' – '+formatCost(max)+' / 1M'}
function modelPriceSignature(x){return ['input_price_micros','cached_price_micros','output_price_micros','long_context_threshold','long_input_price_micros','long_cached_price_micros','long_output_price_micros'].map(key=>Number(x[key])||0).join(':')}
function isOfficialPrice(x){return !!x.pricing_source&&x.pricing_source!=='manual'}
function modelPriceSummary(rows){const priced=rows.filter(routeHasPrice),official=priced.filter(isOfficialPrice),manual=priced.filter(x=>x.pricing_source==='manual'),uniform=new Set(rows.map(modelPriceSignature)).size===1;if(!priced.length)return '<div class="model-price-summary unpriced">'+icon('i-alert')+'<span><strong>尚未定价</strong><small>点“修改统一价格”可一次设置全部渠道</small></span></div>';let detail='';if(manual.length===rows.length&&uniform)detail='手动统一价格 · 应用于 '+rows.length+' 个渠道';else if(official.length===rows.length&&uniform)detail='官方统一价格 · 应用于 '+rows.length+' 个渠道';else if(!uniform)detail='不同渠道价格不一致 · 修改后可一键统一';else detail=priced.length+' / '+rows.length+' 条映射有价格 · '+official.length+' 条官方价格';return '<div class="model-price-summary '+(manual.length?'manual':'')+'">'+icon('i-cost')+'<span><strong>输入 '+priceRange(priced,'input_price_micros')+' · 输出 '+priceRange(priced,'output_price_micros')+'</strong><small>'+detail+'</small></span></div>'}
function renderRoutes(){const q=($('#routeSearch')?.value||'').trim().toLowerCase();const groups=new Map();(cache.routes||[]).forEach(x=>{if(!groups.has(x.public_name))groups.set(x.public_name,[]);groups.get(x.public_name).push(x)});modelSelection.forEach(name=>{if(!groups.has(name))modelSelection.delete(name)});const visible=[...groups.entries()].map(([name,rows])=>[name,rows.sort((a,b)=>(providerPriority(b.provider_id)-providerPriority(a.provider_id))||(a.provider_id-b.provider_id)||(a.id-b.id))]).filter(([name,rows])=>!q||(name+' '+rows.map(x=>x.upstream_model+' '+x.provider_name).join(' ')).toLowerCase().includes(q));$('#routeCount').textContent=(cache.routes||[]).length+' 条映射 · '+groups.size+' 个公开模型';$('#routes').innerHTML=visible.length?visible.map(([name,rows])=>{const enabled=rows.filter(x=>x.enabled&&x.provider_enabled!==false).length,selected=modelSelection.has(name);return '<section class="card simple-route-group '+(selected?'selected':'')+'" data-public-model="'+esc(name)+'"><div class="simple-route-head"><label class="model-row-select" title="选择 '+esc(name)+'"><input type="checkbox" '+(selected?'checked':'')+' onchange="toggleModelSelection('+esc(JSON.stringify(name))+',this.checked)"><span></span></label><div class="simple-route-title"><div class="route-title-line"><h2 class="mono">'+esc(name)+'</h2>'+badge(enabled+' / '+rows.length+' 可用',enabled?'green':'neutral')+'</div><p>同名的 '+rows.length+' 条映射属于同一个故障转移组，共同遵循当前全局调度策略。</p></div>'+modelPriceSummary(rows)+'<div class="model-head-actions"><button class="btn btn-primary btn-sm" onclick="openModelPricing('+esc(JSON.stringify(name))+')">'+icon('i-cost')+'修改统一价格</button><button class="btn btn-danger btn-sm" onclick="deletePublicModel('+esc(JSON.stringify(name))+')">删除整个模型</button></div></div><div class="simple-route-list">'+rows.map(routeRow).join('')+'</div></section>'}).join(''):'<div class="card route-empty"><div class="empty-icon" style="margin:0 auto">'+icon('i-route')+'</div><h3>'+(q?'没有匹配的模型路由':'还没有模型路由')+'</h3><p>'+(q?'换一个关键词试试。':'请在上游渠道或认证文件中点击“识别模型”，勾选需要使用的模型。')+'</p></div>';updateModelSelectionToolbar(visible.map(([name])=>name))}
function routeRow(x){const health=Math.max(0,Math.min(100,Number(x.health_score)||0));const official=isOfficialPrice(x),manual=x.pricing_source==='manual';const updated=x.pricing_updated_at?new Date(x.pricing_updated_at).toLocaleString('zh-CN',{hour12:false}):'';const longContext=Number(x.long_context_threshold)>0?'<div class="route-price-long">≥ '+formatToken(x.long_context_threshold)+' Token：输入 '+formatPrice(x.long_input_price_micros)+' · 缓存 '+formatPrice(x.long_cached_price_micros)+' · 输出 '+formatPrice(x.long_output_price_micros)+'</div>':'';return '<div class="simple-route-row '+((x.enabled&&x.provider_enabled!==false)?'':'inactive')+'"><div class="route-provider"><strong>'+esc(x.provider_name)+'</strong><small>'+routeStatus(x)+' · '+esc(providerTypeLabel(x.provider_type))+'</small></div><div class="route-upstream"><strong class="mono">'+esc(x.upstream_model)+'</strong><small>'+String(x.capabilities||'').split(',').filter(Boolean).map(c=>esc(c)).join(' · ')+'</small></div><div class="route-price-card '+(routeHasPrice(x)?'':'unpriced')+'"><div class="route-price-head"><strong>模型价格</strong><span class="route-price-source">'+(manual?'手动统一':official?'官方同步':'未匹配')+'</span></div><div class="route-price-grid"><span class="route-price-item"><small>输入</small><strong class="route-price-value">'+formatPrice(x.input_price_micros)+'</strong></span><span class="route-price-item"><small>缓存</small><strong class="route-price-value">'+formatPrice(x.cached_price_micros)+'</strong></span><span class="route-price-item output"><small>输出</small><strong class="route-price-value">'+formatPrice(x.output_price_micros)+'</strong></span></div>'+longContext+(updated?'<small class="route-price-updated">更新于 '+esc(updated)+'</small>':'')+'</div><div class="health-meter"><div class="health-top"><span>健康评分</span><strong>'+health+'</strong></div><div class="health-track"><div class="health-fill" style="width:'+health+'%"></div></div><small class="muted">'+(x.provider_first_byte_ms?'首字节 '+x.provider_first_byte_ms+' ms':'总计 '+x.provider_latency_ms+' ms')+' · 失败 '+x.provider_failures+' · 并发 '+x.provider_inflight+'</small></div><div class="route-actions"><button class="btn btn-secondary" onclick="openRouteMapping('+x.id+')">设置统一映射</button><button class="btn btn-danger" onclick="removeItem(&quot;routes&quot;,'+x.id+')">停止此映射</button></div></div>'}
function modelPriceDollars(value){const n=Number(value)||0;return n?String(Math.round(n)/1000000):'0'}
function openRouteMapping(id){const route=(cache.routes||[]).find(x=>x.id===id);if(!route)return notice('这条模型映射已不存在，请刷新后重试',true);routeMappingEditId=id;$('#routeMappingProvider').textContent=route.provider_name||'-';$('#routeMappingUpstream').textContent=route.upstream_model||'-';const names=[...new Set((cache.routes||[]).map(x=>x.public_name))].sort();$('#routePublicNameOptions').innerHTML=names.map(name=>'<option value="'+esc(name)+'"></option>').join('');$('#routeMappingPublicName').value=route.public_name||'';$('#routeMappingModal').classList.remove('hidden');updateRouteMappingPreview();setTimeout(()=>$('#routeMappingPublicName').focus(),50)}
function closeRouteMapping(){$('#routeMappingModal').classList.add('hidden');routeMappingEditId=0}
function updateRouteMappingPreview(){const route=(cache.routes||[]).find(x=>x.id===routeMappingEditId),target=$('#routeMappingPublicName').value.trim().toLowerCase(),host=$('#routeMappingPreview');if(!route||!target){host.textContent='请输入对外统一模型名。';return}const existing=(cache.routes||[]).filter(x=>x.id!==route.id&&x.public_name===target).length;if(target===route.public_name){host.textContent='当前已属于 “'+target+'” 故障转移组，共 '+((cache.routes||[]).filter(x=>x.public_name===target).length)+' 条映射。';return}host.textContent=existing?'保存后会并入 “'+target+'” 的现有故障转移组，与另外 '+existing+' 条映射共同切换。':'保存后会创建 “'+target+'” 故障转移组；后续其他映射使用同名即可自动合并。'}
async function saveRouteMapping(){const route=(cache.routes||[]).find(x=>x.id===routeMappingEditId),name=$('#routeMappingPublicName').value.trim().toLowerCase();if(!route)return notice('这条模型映射已不存在，请刷新后重试',true);if(!name){$('#routeMappingPublicName').focus();return notice('请输入对外统一模型名',true)}const button=$('#routeMappingSave'),original=button.innerHTML;button.disabled=true;button.textContent='正在合并故障转移组…';try{const d=await api('/api/admin/routes/'+route.id,{method:'PATCH',body:JSON.stringify({public_name:name})});closeRouteMapping();await load();focusPublicModel(d.public_name,true);notice('已映射到 '+d.public_name+'；当前故障转移组共有 '+d.group_routes+' 条映射')}catch(e){notice('保存统一映射失败：'+e.message,true)}finally{button.disabled=false;button.innerHTML=original}}
function openModelPricing(name){const rows=cache.routes.filter(x=>x.public_name===name);if(!rows.length)return notice('模型不存在或已被删除',true);pricingEditorModel=name;const base=rows.find(x=>x.pricing_source==='manual')||rows.find(routeHasPrice)||rows[0],fields={pricingInput:'input_price_micros',pricingCached:'cached_price_micros',pricingOutput:'output_price_micros',pricingLongThreshold:'long_context_threshold',pricingLongInput:'long_input_price_micros',pricingLongCached:'long_cached_price_micros',pricingLongOutput:'long_output_price_micros'};Object.entries(fields).forEach(([id,key])=>{$('#'+id).value=id==='pricingLongThreshold'?String(Number(base[key])||0):modelPriceDollars(base[key])});const uniform=new Set(rows.map(modelPriceSignature)).size===1,manual=rows.every(x=>x.pricing_source==='manual'),note=$('#pricingEditorNote');$('#pricingEditorTitle').textContent='修改 '+name+' 的统一价格';$('#pricingEditorSubtitle').textContent='保存一次，将覆盖这个公开模型在全部 '+rows.length+' 个渠道上的价格。';note.classList.toggle('warning',!uniform);note.querySelector('use').setAttribute('href',uniform?'#i-cost':'#i-alert');note.querySelector('span').textContent=!uniform?'当前各渠道价格不一致；保存后会统一覆盖全部 '+rows.length+' 条映射。':manual?'当前是手动统一价格，官方定期同步不会覆盖。':'当前价格一致；保存后会切换为手动统一价格。';$('#pricingRestoreButton').classList.toggle('hidden',!rows.some(x=>x.pricing_source==='manual'));$('#pricingEditorModal').classList.remove('hidden');$('#pricingEditorModal details').open=Number(base.long_context_threshold)>0;setTimeout(()=>$('#pricingInput').focus(),50)}
function closeModelPricing(){$('#pricingEditorModal').classList.add('hidden');pricingEditorModel=''}
function pricingMicros(id){const raw=$('#'+id).value.trim(),value=raw===''?0:Number(raw);if(!Number.isFinite(value)||value<0||value>1000000)throw Error('价格必须是 0 到 1,000,000 之间的数字');return Math.round(value*1000000)}
async function saveModelPricing(){if(!pricingEditorModel)return;const button=$('#pricingSaveButton'),original=button.innerHTML;let payload;try{const threshold=Number($('#pricingLongThreshold').value||0);if(!Number.isInteger(threshold)||threshold<0||threshold>100000000)throw Error('长上下文阈值必须是 0 到 100,000,000 的整数');payload={input_price_micros:pricingMicros('pricingInput'),cached_price_micros:pricingMicros('pricingCached'),output_price_micros:pricingMicros('pricingOutput'),long_context_threshold:threshold,long_input_price_micros:pricingMicros('pricingLongInput'),long_cached_price_micros:pricingMicros('pricingLongCached'),long_output_price_micros:pricingMicros('pricingLongOutput')}}catch(e){return notice(e.message,true)}button.disabled=true;button.textContent='正在统一价格…';try{const d=await api('/api/admin/models/'+encodeURIComponent(pricingEditorModel)+'/pricing',{method:'PATCH',body:JSON.stringify(payload)});notice('已统一 '+d.updated_routes+' 条渠道映射的价格');closeModelPricing();await load()}catch(e){notice('保存价格失败：'+e.message,true)}finally{button.disabled=false;button.innerHTML=original}}
async function restoreModelPricing(){if(!pricingEditorModel||!confirm('恢复官方价格同步？\n\n系统会立即查询官方定价并重新应用到这个模型的各渠道。'))return;const button=$('#pricingRestoreButton'),original=button.textContent;button.disabled=true;button.textContent='正在查询官方价格…';try{const d=await api('/api/admin/models/'+encodeURIComponent(pricingEditorModel)+'/pricing/official',{method:'POST',body:JSON.stringify({})});notice(d.updated_routes?'已恢复官方价格，共更新 '+d.updated_routes+' 条映射':'已恢复官方同步，但当前没有匹配到官方价格',!d.updated_routes);closeModelPricing();await load()}catch(e){notice('恢复官方价格失败：'+e.message,true)}finally{button.disabled=false;button.textContent=original}}
function toggleModelSelection(name,checked){checked?modelSelection.add(name):modelSelection.delete(name);renderRoutes()}
function selectVisiblePublicModels(checked){const q=($('#routeSearch')?.value||'').trim().toLowerCase();const names=[...new Set(cache.routes.filter(x=>!q||(x.public_name+' '+x.upstream_model+' '+x.provider_name).toLowerCase().includes(q)).map(x=>x.public_name))];names.forEach(name=>checked?modelSelection.add(name):modelSelection.delete(name));renderRoutes()}
function updateModelSelectionToolbar(visibleNames=[]){visibleNames=Array.isArray(visibleNames)?visibleNames:[];const count=modelSelection.size,button=$('#deleteSelectedModelsButton'),label=$('#selectedModelCount'),selectAll=$('#selectAllModels');if(label)label.textContent=count?('已选择 '+count+' 个模型'):'未选择模型';if(button)button.disabled=count===0;if(selectAll){const selectedVisible=visibleNames.filter(name=>modelSelection.has(name)).length;selectAll.checked=visibleNames.length>0&&selectedVisible===visibleNames.length;selectAll.indeterminate=selectedVisible>0&&selectedVisible<visibleNames.length}}
async function startModelHealthCheck(routes,scope){if(!routes.length)return notice('没有可检活的启用聊天模型映射',true);if(routes.length>1000)return notice('单次最多检活 1000 条模型映射',true);const providerIDs=[...new Set(routes.map(x=>Number(x.provider_id)))],routeIDs=scope==='selected'?routes.map(x=>Number(x.id)):[];try{const job=await api('/api/admin/health-checks',{method:'POST',body:JSON.stringify({provider_ids:providerIDs,route_ids:routeIDs,model_scope:scope})});healthCheckTask.id=job.id;healthCheckTask.job=job;renderModelHealthCheckJob(job);updateModelSelectionToolbar();notice('已开始真实检活 '+job.total+' 条模型映射');scheduleHealthCheckPoll(150)}catch(e){notice('无法开始模型检活：'+e.message,true);await resumeActiveHealthCheck(true)}}
async function deleteSelectedModels(){const models=[...modelSelection];if(!models.length)return;if(!confirm('确认删除所选 '+models.length+' 个公开模型？\n\n这会删除它们在全部渠道上的映射。OAuth 自动同步不会重新添加；之后仍可通过“识别并批量添加”手动恢复。'))return;const button=$('#deleteSelectedModelsButton'),original=button.innerHTML;button.disabled=true;button.textContent='正在删除…';try{const d=await api('/api/admin/models',{method:'DELETE',body:JSON.stringify({models})});modelSelection.clear();notice('已删除 '+d.deleted_models+' 个模型，共 '+d.deleted_routes+' 条映射');await load()}catch(e){notice(e.message,true)}finally{button.disabled=false;button.innerHTML=original}}
async function deletePublicModel(name){if(!confirm('确认删除公开模型 '+name+'？\n\n这会删除它在所有渠道上的映射，并阻止 OAuth 自动同步重新添加。之后可通过“识别并批量添加”手动恢复。'))return;try{const d=await api('/api/admin/models/'+encodeURIComponent(name),{method:'DELETE'});modelSelection.delete(name);notice('已删除 '+d.deleted_routes+' 条模型映射');await load()}catch(e){notice(e.message,true)}}
function focusPublicModel(name,filter=true){name=String(name||'').toLowerCase();if(!name)return;showPage('routes');const search=$('#routeSearch');if(filter&&search){search.value=name;renderRoutes()}setTimeout(()=>{const group=$$('.simple-route-group').find(x=>x.dataset.publicModel===name);if(!group)return;group.classList.remove('focus-pulse');void group.offsetWidth;group.classList.add('focus-pulse');group.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>group.classList.remove('focus-pulse'),1800)},60)}
function focusUnpricedModels(){const route=(cache.routes||[]).find(x=>!routeHasPrice(x));if(!route)return notice('当前所有模型都已有价格');focusPublicModel(route.public_name,true);notice('已定位到 '+route.public_name+'，点击“修改统一价格”即可设置')}
function renderPricingOverview(){const host=$('#pricingOverview');if(!host)return;const routes=cache.routes||[],priced=routes.filter(routeHasPrice),official=priced.filter(isOfficialPrice),manual=priced.filter(x=>x.pricing_source==='manual'),unpriced=routes.filter(x=>!routeHasPrice(x)),status=cache.pricing?.status||{},last=status.pricing_last_sync;host.innerHTML='<div class="pricing-overview-head"><div><span class="pricing-kicker">PRICE VISIBILITY</span><h2>'+icon('i-cost')+'模型价格总览</h2></div><button class="btn btn-primary btn-sm" onclick="showPage(&quot;usage&quot;)">查看实际费用</button></div><div class="pricing-overview-grid"><div class="pricing-metric primary"><strong>'+priced.length+'</strong><span>已定价映射</span><small>共 '+routes.length+' 条</small></div><div class="pricing-metric"><strong>'+official.length+'</strong><span>官方价格</span><small>Claude 等自动查询</small></div><div class="pricing-metric"><strong>'+manual.length+'</strong><span>手动统一价格</span><small>不会被官方同步覆盖</small></div><button type="button" class="pricing-metric pricing-metric-action '+(unpriced.length?'warning':'')+'" onclick="focusUnpricedModels()" '+(unpriced.length?'':'disabled')+'><strong>'+unpriced.length+'</strong><span>未定价映射</span><small>'+(unpriced.length?'点击定位到第一个未定价模型':'价格覆盖完整')+'</small></button></div><div class="pricing-overview-foot">'+icon(last?'i-check':'i-alert')+'<span>'+(last?'最近同步 '+esc(new Date(last).toLocaleString('zh-CN',{hour12:false})):'尚未同步官方价格')+'；每个公开模型可点“修改统一价格”，一次应用到全部渠道。</span></div>'}
function renderPricingStatus(){const host=$('#pricingStatus'),status=cache.pricing?.status||{},last=status.pricing_last_sync;if(!host)return;host.innerHTML=icon('i-cost')+(last?'官方价格上次同步：'+esc(new Date(last).toLocaleString('zh-CN',{hour12:false}))+' · 更新 '+esc(status.pricing_last_updated_routes||'0')+' 条路由':'官方价格尚未同步；点击右上角“同步官方价格”立即查询 OpenAI、Gemini、Grok 与 Anthropic Claude 官方价格')+(status.pricing_last_error?' · <span class="coverage-warn">部分失败：'+esc(status.pricing_last_error)+'</span>':'');renderPricingOverview()}
async function syncPricing(){const button=$('#pricingSyncButton'),original=button.innerHTML;button.disabled=true;button.textContent='正在实时查询价格…';try{const d=await api('/api/admin/pricing',{method:'POST'}),warning=(d.errors?.length?'，'+d.errors.length+' 个来源或匹配警告':'');notice('价格同步完成：'+d.models+' 个模型，更新 '+d.updated_routes+' 条路由'+warning,!!d.errors?.length);await load()}catch(e){notice('价格同步失败：'+e.message,true)}finally{button.disabled=false;button.innerHTML=original}}
function availableKeyModels(){return [...new Set(cache.routes.filter(x=>x.enabled!==false&&x.provider_enabled!==false).map(x=>String(x.public_name||'').trim().toLowerCase()).filter(Boolean))].sort()}
function filteredKeyModels(){const q=($('#keyModelSearch')?.value||'').trim().toLowerCase();return availableKeyModels().filter(x=>!q||x.includes(q))}
function resetKeyPermissions(){keyPermissions={allowed:new Set(),denied:new Set()};const form=$('#keyForm');if(form){form.reset();$('#keyAllowAll').checked=true}if($('#keyModelSearch'))$('#keyModelSearch').value='';renderKeyModelPermissions()}
function keyAllowAllChanged(){if($('#keyAllowAll').checked)keyPermissions.allowed.clear();renderKeyModelPermissions()}
function setKeyPermission(model,kind,checked){if(kind==='allow'){if(checked){$('#keyAllowAll').checked=false;keyPermissions.allowed.add(model);keyPermissions.denied.delete(model)}else keyPermissions.allowed.delete(model)}else{if(checked){keyPermissions.denied.add(model);keyPermissions.allowed.delete(model)}else keyPermissions.denied.delete(model)}renderKeyModelPermissions()}
function setVisibleKeyPermission(kind){const models=filteredKeyModels();if(kind==='allow')$('#keyAllowAll').checked=false;models.forEach(model=>{if(kind==='allow'){keyPermissions.allowed.add(model);keyPermissions.denied.delete(model)}else{keyPermissions.denied.add(model);keyPermissions.allowed.delete(model)}});renderKeyModelPermissions()}
function clearKeyPermissions(){keyPermissions.allowed.clear();keyPermissions.denied.clear();renderKeyModelPermissions()}
function renderKeyModelPermissions(){const list=$('#keyModelList');if(!list)return;const all=availableKeyModels(),models=filteredKeyModels(),allowAll=$('#keyAllowAll')?.checked??true;list.innerHTML=models.length?models.map(model=>'<div class="permission-row"><span class="permission-model" title="'+esc(model)+'">'+esc(model)+'</span><label class="permission-check '+(allowAll?'disabled':'')+'"><input type="checkbox" '+(keyPermissions.allowed.has(model)?'checked':'')+' '+(allowAll?'disabled':'')+' data-model="'+esc(model)+'" onchange="setKeyPermission(this.dataset.model,&quot;allow&quot;,this.checked)">允许</label><label class="permission-check deny"><input type="checkbox" '+(keyPermissions.denied.has(model)?'checked':'')+' data-model="'+esc(model)+'" onchange="setKeyPermission(this.dataset.model,&quot;deny&quot;,this.checked)">拒绝</label></div>').join(''):'<div class="permission-empty">'+(all.length?'没有符合搜索条件的模型':'暂无可用模型，请先添加并启用模型路由')+'</div>';$('#keyModelAvailability').textContent=all.length+' 个可用模型';$('#keyPermissionSummary').textContent=(allowAll?'全部模型':'允许 '+keyPermissions.allowed.size+' 个')+(keyPermissions.denied.size?' · 拒绝 '+keyPermissions.denied.size+' 个':'')}
function keyPermissionLabel(x){const allow=x.allow_all?'全部模型':((x.allow_models||'').split(',').filter(Boolean).length+' 个允许');const denied=(x.deny_models||'').split(',').filter(Boolean).length;return allow+(denied?' · '+denied+' 个拒绝':'')}
function renderKeys(){$('#keyCount').textContent=cache.keys.length+' 把';const nowMS=Date.now();$('#keys').innerHTML=cache.keys.length?cache.keys.map(x=>{let actions='';if(x.can_reveal)actions+='<button class="btn btn-secondary" onclick="revealKey('+x.id+')">'+icon('i-copy')+'复制</button> ';else actions+='<span class="muted legacy-key">旧 Key 不可恢复</span> ';actions+='<button class="btn btn-danger" onclick="removeItem(\'keys\','+x.id+')">删除</button>';const expires=x.expires_at?new Date(x.expires_at):null,expired=expires&&expires.getTime()<=nowMS,budgeted=Number(x.budget_micros)>0,exhausted=budgeted&&Number(x.remaining_micros)<=0;let state=x.revoked?badge('已撤销','red',true):expired?badge('已到期','red',true):exhausted?badge('预算耗尽','red',true):badge('有效','green',true);const budget=budgeted?'<strong>'+formatCost(x.budget_micros)+'</strong><div class="muted">已用 '+formatCost(x.spent_micros)+' · 剩余 '+formatCost(x.remaining_micros)+'</div>':'不限<div class="muted">已用 '+formatCost(x.spent_micros)+'</div>';return '<tr><td><span class="primary-cell">'+esc(x.name)+'</span></td><td class="mono">'+esc(x.prefix)+'••••••</td><td>'+esc(keyPermissionLabel(x))+'</td><td>'+(x.allow_images?badge('允许','blue'):badge('禁止','neutral'))+'</td><td>'+x.rpm_limit+'</td><td>'+budget+'</td><td>'+(expires?expires.toLocaleString('zh-CN',{hour12:false}):'永久')+'</td><td>'+new Date(x.created_at).toLocaleString('zh-CN',{hour12:false})+'</td><td>'+state+'</td><td><div class="key-actions">'+actions+'</div></td></tr>'}).join(''):emptyRow(10,'i-key','还没有访问密钥','创建一把下游 Key，然后把统一 Base URL 和 Key 填入你的 AI 客户端。','<button class="btn btn-primary" onclick="togglePanel(\'keyPanel\',true)">'+icon('i-plus')+'创建第一把 Key</button>')}
function usageOption(select,items,placeholder,label){if(!select)return;const current=select.value;select.innerHTML='<option value="">'+placeholder+'</option>'+items.map(x=>'<option value="'+esc(x.value)+'">'+esc(label(x))+'</option>').join('');if([...select.options].some(x=>x.value===current))select.value=current}
function renderUsageFilterOptions(){usageOption($('#usageKey'),cache.keys.map(x=>({value:x.id,...x})),'全部 Key',x=>x.name+' · '+x.prefix+'••••');usageOption($('#usageProvider'),cache.providers.map(x=>({value:x.id,...x})),'全部渠道',x=>x.name);const models=[...new Set(cache.routes.map(x=>String(x.public_name||'').toLowerCase()).filter(Boolean))].sort();usageOption($('#usageModel'),models.map(x=>({value:x,name:x})),'全部模型',x=>x.name)}
function usageRangeDays(value){const hours=Math.max(1,Number(value)||720);return Math.max(1,Math.ceil(hours/24))}
function setUsageTimeRange(value,load=true){if(value==='custom')return;const hours=Math.max(1,Number(value)||720),to=new Date(),from=new Date(to.getTime()-hours*3600000);$('#usageFrom').value=localDateTimeValue(from);$('#usageTo').value=localDateTimeValue(to);if(load)loadTokenUsage(1)}
function usageTimeChanged(){if($('#usageDays'))$('#usageDays').value='custom'}
function usageParams(page=1){const range=$('#usageDays')?.value||'720';if(!$('#usageFrom')?.value||!$('#usageTo')?.value)setUsageTimeRange(range==='custom'?'720':range,false);const p=new URLSearchParams({days:String(range==='custom'?30:usageRangeDays(range)),page:String(page),page_size:'50'}),from=$('#usageFrom')?.value,to=$('#usageTo')?.value,key=$('#usageKey')?.value,provider=$('#usageProvider')?.value,model=$('#usageModel')?.value,status=$('#usageStatus')?.value,protocol=$('#usageProtocol')?.value,stream=$('#usageStream')?.value;if(from)p.set('from',new Date(from).toISOString());if(to)p.set('to',new Date(to).toISOString());if(key)p.set('api_key_id',key);if(provider)p.set('provider_id',provider);if(model)p.set('model',model);if(status&&status!=='all')p.set('status',status);if(protocol)p.set('protocol',protocol);if(stream)p.set('stream',stream);return p}
async function loadTokenUsage(page=1){const button=$('#usageRefresh'),original=button?.innerHTML;if(button){button.disabled=true;button.textContent='统计中…'}try{cache.usage=await api('/api/admin/token-usage?'+usageParams(page));renderTokenUsage()}catch(e){notice('Token 统计加载失败：'+e.message,true)}finally{if(button){button.disabled=false;button.innerHTML=original}}}
function usageStat(label,value,foot,tone,iconId='i-cost'){return '<div class="usage-stat" style="--usage-tone:'+tone+'"><div class="usage-stat-top"><span>'+label+'</span><span class="usage-stat-icon">'+icon(iconId)+'</span></div><div class="usage-stat-value">'+value+'</div><div class="usage-stat-foot">'+foot+'</div></div>'}
function formatPercent(value){const n=Math.max(0,Math.min(100,Number(value)||0));return n.toFixed(n===100?0:1)+'%'}
function renderTokenUsage(){const d=cache.usage;if(!d)return;const t=d.totals;$('#usageSummary').innerHTML=usageStat('估算费用',formatCost(t.cost_micros),'官方价格覆盖 '+formatPercent(t.cost_coverage),'#ffbd72','i-cost')+usageStat('总 Token',formatToken(t.total_tokens),'输入 + 输出，不重复累计缓存/推理','var(--accent)')+usageStat('输入 Token',formatToken(t.input_tokens),formatToken(t.requests)+' 个请求 · '+formatToken(t.attempts)+' 次尝试','var(--blue)','i-activity')+usageStat('输出 Token',formatToken(t.output_tokens),'模型生成内容','var(--orange)','i-model')+usageStat('缓存 / 推理',formatToken(t.cached_tokens)+' / '+formatToken(t.reasoning_tokens),'缓存命中 / 单独报告的推理量','#b19cff','i-database')+usageStat('Usage 采集率',formatPercent(t.usage_coverage),formatToken(t.reported_requests)+' / '+formatToken(t.successful_requests)+' 个成功请求','var(--accent)','i-check');renderUsageChart(d.series);renderUsageRanks($('#usageKeyRanks'),d.by_keys,'key','var(--accent)');renderUsageRanks($('#usageProviderRanks'),d.by_providers,'provider','var(--blue)');renderUsageRanks($('#usageModelRanks'),d.by_models,'model','var(--orange)');renderUsageDetails(d);animateCountUp()}
function renderUsageChart(series){const host=$('#usageChart');const rows=Array.isArray(series)?series:[];const max=Math.max(0,...rows.map(x=>Number(x.total_tokens)||0)),range=$('#usageDays'),rangeLabel=range&&range.value!=='custom'?range.options[range.selectedIndex]?.textContent:(cache.usage?.period?.days||30)+' 天';$('#usageChartSubtitle').textContent=rangeLabel+' · 按 UTC 自然日聚合 · 悬停柱形可查看明细';if(!rows.length||max===0){host.innerHTML='<div class="usage-chart-empty">当前筛选范围还没有已采集的 Token 数据</div>';return}const W=1000,H=270,L=48,R=12,T=14,B=31,plotW=W-L-R,plotH=H-T-B,step=plotW/rows.length,bar=Math.max(.9,Math.min(12,step*.68));let svg='<svg class="usage-chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="每日 Token 趋势图">';for(let i=0;i<=4;i++){const y=T+plotH*i/4;svg+='<line class="grid" x1="'+L+'" y1="'+y+'" x2="'+(W-R)+'" y2="'+y+'"/><text x="'+(L-7)+'" y="'+(y+3)+'" text-anchor="end">'+formatToken(max*(4-i)/4)+'</text>'}let points=[];rows.forEach((x,i)=>{const input=Math.max(0,Number(x.input_tokens)||0),output=Math.max(0,Number(x.output_tokens)||0),total=input+output,cx=L+step*(i+.5),inputH=plotH*input/max,outputH=plotH*output/max,yInput=T+plotH-inputH,yOutput=yInput-outputH;svg+='<g><title>'+esc(x.date)+' · 总计 '+formatToken(total)+' · 输入 '+formatToken(input)+' · 输出 '+formatToken(output)+' · 缓存 '+formatToken(x.cached_tokens)+' · 推理 '+formatToken(x.reasoning_tokens)+'</title>';if(inputH>0)svg+='<rect x="'+(cx-bar/2)+'" y="'+yInput+'" width="'+bar+'" height="'+inputH+'" rx="'+Math.min(2,bar/3)+'" fill="var(--blue)" opacity=".78"/>';if(outputH>0)svg+='<rect x="'+(cx-bar/2)+'" y="'+yOutput+'" width="'+bar+'" height="'+outputH+'" rx="'+Math.min(2,bar/3)+'" fill="var(--orange)" opacity=".86"/>';svg+='</g>';points.push(cx+','+(T+plotH-plotH*total/max))});svg+='<polyline class="total-line" points="'+points.join(' ')+'"/>';const labels=Math.min(6,rows.length);for(let i=0;i<labels;i++){const index=Math.round(i*(rows.length-1)/Math.max(1,labels-1)),x=L+step*(index+.5),date=rows[index].date.slice(5);svg+='<text x="'+x+'" y="'+(H-7)+'" text-anchor="middle">'+esc(date)+'</text>'}svg+='</svg>';host.innerHTML=svg}
function renderUsageRanks(host,rows,type,tone){rows=Array.isArray(rows)?rows:[];if(!rows.length){host.innerHTML='<div class="rank-empty">暂无可排行数据</div>';return}const max=Math.max(1,...rows.map(x=>Number(x.total_tokens)||0));host.innerHTML=rows.map((x,i)=>{let sub='',name=x.name||'未命名';if(type==='key')sub=(x.prefix?x.prefix+'•••• · ':'')+formatToken(x.requests)+' 个请求';else if(type==='provider')sub=formatToken(x.requests)+' 个请求 · '+formatToken(x.attempts)+' 次尝试';else sub=(x.upstream_model&&x.upstream_model!==x.name?'上游 '+x.upstream_model+' · ':'')+formatToken(x.requests)+' 个请求';sub+=' · '+formatCost(x.cost_micros);return '<div class="rank-item" style="--rank-tone:'+tone+'"><div class="rank-line"><div class="rank-name">'+(i+1)+'. '+esc(name)+'<span class="rank-sub">'+esc(sub)+'</span></div><span class="rank-value">'+formatToken(x.total_tokens)+'</span></div><div class="rank-track"><div class="rank-fill" style="width:'+Math.max(2,(Number(x.total_tokens)||0)*100/max)+'%"></div></div></div>'}).join('')}
function renderUsageDetails(d){const rows=Array.isArray(d.details)?d.details:[];$('#usageDetailCount').textContent='第 '+d.page+' 页 · '+rows.length+' 组';$('#usageDetails').innerHTML=rows.length?rows.map(x=>'<tr><td>'+esc(x.date)+'</td><td><span class="usage-key">'+esc(x.api_key_name||'未命名密钥')+'</span><div class="muted mono">'+esc(x.api_key_prefix?x.api_key_prefix+'••••':'无前缀快照')+'</div></td><td>'+esc(x.provider_name||'已删除渠道')+'</td><td><span class="usage-model">'+esc(x.public_model||'—')+'</span><div class="muted usage-model">'+esc(x.upstream_model||'—')+'</div></td><td><strong>'+formatToken(x.requests)+'</strong><div class="muted">'+formatToken(x.attempts)+' 次尝试</div></td><td class="mono">'+formatToken(x.input_tokens)+'</td><td class="mono">'+formatToken(x.output_tokens)+'</td><td class="mono">'+formatToken(x.cached_tokens)+'</td><td class="mono">'+formatToken(x.reasoning_tokens)+'</td><td class="mono"><strong>'+formatToken(x.total_tokens)+'</strong></td><td class="mono"><strong>'+formatCost(x.cost_micros)+'</strong></td><td><span class="'+(Number(x.usage_coverage)>=99.95?'coverage-good':'coverage-warn')+'">'+formatPercent(x.usage_coverage)+'</span><div class="muted">计价 '+formatPercent(x.cost_coverage)+'</div></td></tr>').join(''):emptyRow(12,'i-cost','暂无用量明细','当前范围没有已完成请求，或筛选条件没有匹配数据。','');$('#usagePagination').innerHTML='<button class="btn btn-secondary btn-sm" '+(d.page<=1?'disabled':'')+' onclick="loadTokenUsage('+(d.page-1)+')">上一页</button><span>第 '+d.page+' 页</span><button class="btn btn-secondary btn-sm" '+(!d.has_more?'disabled':'')+' onclick="loadTokenUsage('+(d.page+1)+')">下一页</button>'}
function formatDuration(ms){if(ms===null||ms===undefined||Number.isNaN(Number(ms)))return '—';ms=Math.max(0,Number(ms));return ms>=1000?(ms/1000).toFixed(ms<10000?2:1)+' s':Math.round(ms)+' ms'}
function requestRuntime(x){if(!x.running)return x.latency_ms;const started=new Date(x.created_at).getTime();return Number.isFinite(started)?Date.now()-started:0}
function formatRequestTime(value){if(!value)return '—';const date=new Date(value);if(Number.isNaN(date.getTime()))return value;const parts=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).formatToParts(date),get=type=>parts.find(x=>x.type===type)?.value||'';return get('year')+'-'+get('month')+'-'+get('day')+' '+get('hour')+':'+get('minute')+':'+get('second')}
function localDateTimeValue(date){const pad=value=>String(value).padStart(2,'0');return date.getFullYear()+'-'+pad(date.getMonth()+1)+'-'+pad(date.getDate())+'T'+pad(date.getHours())+':'+pad(date.getMinutes())+':'+pad(date.getSeconds())}
function setRequestTimeRange(value,load=true){if(value==='custom')return;const hours=Math.max(1,Number(value)||24),to=new Date(),from=new Date(to.getTime()-hours*3600000);$('#requestFrom').value=localDateTimeValue(from);$('#requestTo').value=localDateTimeValue(to);if(load)loadRequestsOnly()}
function requestFilterChanged(){if($('#requestRange'))$('#requestRange').value='custom';loadRequestsOnly()}
function requestParams(){const range=$('#requestRange')?.value||'24';if(range!=='custom')setRequestTimeRange(range,false);const params=new URLSearchParams({limit:$('#requestLimit')?.value||'50',status:$('#requestStatus')?.value||'all'}),from=$('#requestFrom')?.value,to=$('#requestTo')?.value,provider=$('#requestProvider')?.value,query=$('#requestSearch')?.value.trim();if(from)params.set('from',new Date(from).toISOString());if(to)params.set('to',new Date(to).toISOString());if(provider)params.set('provider_id',provider);if(query)params.set('q',query);return params}
function scheduleRequestFilter(){clearTimeout(requestFilterTimer);requestFilterTimer=setTimeout(loadRequestsOnly,350)}
function renderRequestProviderOptions(){const select=$('#requestProvider');if(!select)return;const previous=select.value;select.innerHTML='<option value="">全部渠道</option>'+cache.providers.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('');if(previous&&[...select.options].some(x=>x.value===previous))select.value=previous}
function resetRequestFilters(){if($('#requestStatus'))$('#requestStatus').value='all';if($('#requestProvider'))$('#requestProvider').value='';if($('#requestLimit'))$('#requestLimit').value='50';if($('#requestSearch'))$('#requestSearch').value='';if($('#requestRange'))$('#requestRange').value='24';setRequestTimeRange('24')}
function reasoningEffortChip(effort){if(!effort)return '';const label={none:'无推理',minimal:'极简',low:'低',medium:'中',high:'高',xhigh:'超高'}[effort]||effort;return '<span class="reasoning-chip reasoning-'+esc(effort)+'" title="推理强度：'+esc(label)+'">'+icon('i-activity')+esc(label)+'</span>'}
let requestRenderState=null;function requestRowHTML(x){const errorLabel=requestReasonLabel(x.error_type)||('HTTP '+(x.status_code||'失败')),retryLabel=requestReasonLabel(x.retry_reason),state=x.running?'<span class="running-status"><i class="live-dot"></i>进行中</span>':x.success?'<span class="result-ok">✓ 成功</span>':'<span class="result-fail">× '+esc(errorLabel)+'</span>';return '<tr data-id="'+x.id+'"><td class="request-time"><strong>'+esc(formatRequestTime(x.created_at))+'</strong><small>'+(x.running?'尚未完成':esc(formatRequestTime(x.completed_at)))+'</small></td><td class="mono">'+esc(x.client_ip||'未记录')+'<div class="muted">'+(x.stream?'流式':'非流式')+' · '+esc(x.protocol||'未知协议')+'</div></td><td>'+esc(x.provider_name||'—')+'</td><td class="primary-cell">'+esc(x.model)+reasoningEffortChip(x.reasoning_effort)+'</td><td>'+state+(retryLabel?'<div class="muted">上次尝试：'+esc(retryLabel)+'</div>':'')+'</td><td><span class="duration-main">'+formatDuration(x.first_byte_ms)+'</span><div class="muted duration-sub">上游首字节</div></td><td><span class="duration-main">'+formatDuration(requestRuntime(x))+'</span><div class="muted duration-sub">'+(x.running?'实时计时':'已完成')+'</div></td><td class="mono token-cell">'+tokenDetails(x)+'</td></tr>'}function renderRequests(){const rows=cache.requests;$('#requestCount').textContent=rows.length+' 条结果'+(rows.some(x=>x.running)?' · 有进行中请求':'');const tbody=$('#requests');const ids=rows.map(x=>x.id);const running=new Set();rows.forEach(x=>{if(x.running)running.add(x.id)});const prev=requestRenderState;if(prev&&prev.ids.length===ids.length&&ids.every((id,i)=>id===prev.ids[i])){for(const x of rows){const was=prev.running.has(x.id);if(was&&x.running){const tr=tbody.querySelector('tr[data-id="'+x.id+'"]');if(tr&&tr.children.length>=8){tr.children[6].innerHTML='<span class="duration-main">'+formatDuration(requestRuntime(x))+'</span><div class="muted duration-sub">实时计时</div>'}}else if(was!==x.running){const tr=tbody.querySelector('tr[data-id="'+x.id+'"]');if(tr){tr.outerHTML=requestRowHTML(x)}}}requestRenderState={ids,running};return}tbody.innerHTML=rows.length?rows.map(requestRowHTML).join(''):emptyRow(8,'i-list','没有符合条件的请求','调整时间、状态、渠道或关键词后重试。','<button class="btn btn-secondary" onclick="resetRequestFilters()">重置筛选</button>');requestRenderState={ids,running}}
let requestDataSnapshot='';async function loadRequestsOnly(){try{const rows=await api('/api/admin/requests?'+requestParams());const snap=JSON.stringify(rows.map(x=>[x.id,x.running,x.completed_at,x.first_byte_ms,x.status_code,x.error_type,x.input_tokens,x.output_tokens,x.cached_tokens,x.reasoning_tokens,x.latency_ms]));if(snap===requestDataSnapshot)return;requestDataSnapshot=snap;cache.requests=rows;renderRequests()}catch(e){notice('请求账本加载失败：'+e.message,true)}}
function manageRequestPolling(page){clearInterval(requestPollTimer);clearInterval(requestClockTimer);requestPollTimer=0;requestClockTimer=0;if(page!=='requests')return;renderRequestProviderOptions();if(!$('#requestFrom')?.value)setRequestTimeRange($('#requestRange')?.value||'24',false);loadRequestsOnly();if(document.hidden)return;requestPollTimer=setInterval(loadRequestsOnly,5000);requestClockTimer=setInterval(()=>{if(cache.requests.some(x=>x.running))renderRequests()},2000)}
function qualityStatusView(status){return ({idle:['空闲','neutral'],running:['检测中','blue'],stopping:['停止中','orange'],complete:['已完成','green'],stopped:['已停止','orange'],interrupted:['可恢复','orange'],error:['失败','red']})[status]||[status||'未知','neutral']}
function renderQualityEstimate(){const preset=$('#qualityPreset')?.value||'low',estimate=cache.quality?.estimates?.[preset];if(!estimate){$('#qualityEstimate').textContent='该档位成本暂不可用';return}const total=Number(estimate.total_requests||0),long=Number(estimate.fixed_32k_requests||0),tokens=Number(estimate.approximate_fixed_32k_input_tokens||0);$('#qualityEstimate').innerHTML='<strong>预计 '+formatToken(total)+' 个逻辑请求</strong><span>'+(long?formatToken(long)+' 个固定 32K 请求 · 约 '+formatToken(tokens)+' 长上下文输入 Token':'不包含固定 32K 长上下文请求')+'</span>'}
function qualityTargets(){return Array.isArray(cache.quality?.targets)?cache.quality.targets:[]}
function renderQualityTargets(){const model=$('#qualityModel').value,targets=qualityTargets().filter(x=>x.model===model),provider=$('#qualityProvider'),selected=provider.value,providers=[];targets.forEach(x=>{if(!providers.some(item=>String(item.id)===String(x.provider_id)))providers.push({id:x.provider_id,name:x.provider_name,type:x.provider_type})});provider.innerHTML=providers.length?providers.map(x=>'<option value="'+x.id+'" '+(String(x.id)===selected?'selected':'')+'>'+esc(x.name)+' · '+esc(x.type)+'</option>').join(''):'<option value="">没有可检测渠道</option>';renderQualityCredentials()}
function renderQualityCredentials(){const model=$('#qualityModel').value,providerId=$('#qualityProvider').value,credential=$('#qualityCredential'),selected=credential.value,targets=qualityTargets().filter(x=>x.model===model&&String(x.provider_id)===providerId);credential.innerHTML=targets.length?targets.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===selected?'selected':'')+'>'+esc(x.provider_key_name||'渠道凭据')+(x.provider_key_hint?' · '+esc(x.provider_key_hint):'')+'</option>').join(''):'<option value="">没有适用凭据</option>';renderQualityTargetSummary()}
function selectedQualityTarget(){const id=$('#qualityCredential')?.value;return qualityTargets().find(x=>x.id===id)}
function qualityTargetText(target){return target?target.model+' → '+target.provider_name+' → '+(target.provider_key_name||'渠道凭据')+(target.provider_key_hint?' ('+target.provider_key_hint+')':''):'没有与该模型匹配的可用渠道和凭据'}
function renderQualityTargetSummary(){const target=selectedQualityTarget();$('#qualityTargetSummary').innerHTML=target?'<strong>本次锁定</strong><span>'+esc(qualityTargetText(target))+' · 上游模型 '+esc(target.upstream_model)+'</span>':'<strong>无法开始</strong><span>请先在模型路由和渠道凭据中启用一条兼容路由。</span>';$('#qualityStart').disabled=!target}
async function loadQualityMeta(){try{cache.quality=await api('/api/admin/quality-detector');$('#qualityDetectorVersion').textContent='GPT-5.6 Detector '+(cache.quality.version||'');$('#qualityAvailability').className='badge green';$('#qualityAvailability').textContent='侧车正常';renderQualityTargets();renderQualityEstimate()}catch(e){cache.quality=null;$('#qualityDetectorVersion').textContent='检测器未连接';$('#qualityAvailability').className='badge red';$('#qualityAvailability').textContent='不可用';$('#qualityTargetSummary').textContent=e.message;$('#qualityEstimate').textContent=e.message}}
function renderQualityStatus(status){const view=qualityStatusView(status.status),target=status.fusiongate_target;$('#qualityStatus').className='badge '+view[1];$('#qualityStatus').textContent=view[0];$('#qualityUpdated').textContent=status.updated_at?'更新于 '+formatRequestTime(status.updated_at):'尚未运行';$('#qualitySession').textContent='会话 '+(status.session_id||'—')+(status.claimed_model?' · '+status.claimed_model:'')+(target?' · '+qualityTargetText(target):'');const progress=status.progress||{},planned=Number(progress.planned||0),completed=Number(progress.logical_completed??(Number(progress.successful||0)+Number(progress.errors||0)+Number(progress.cancelled||0))),successful=Number(progress.successful||0),errors=Number(progress.errors||0);$('#qualityProgressBar').style.width=(planned?Math.min(100,completed*100/planned):0)+'%';$('#qualityMetrics').innerHTML=[['计划任务',planned],['已完成',completed],['成功',successful],['错误',errors]].map(([label,value])=>'<div><span>'+label+'</span><strong>'+formatToken(value)+'</strong></div>').join('');const running=['running','stopping'].includes(status.status);$('#qualityStart').disabled=running||!selectedQualityTarget();$('#qualityStop').classList.toggle('hidden',!running);if(status.error)notice('质量检测失败：'+status.error,true)}
function qualityItemText(item){if(typeof item==='string')return item;if(!item)return '未知项目';return item.title||item.reason||item.name||JSON.stringify(item)}
function renderQualityReport(report){const root=$('#qualityReport');root.classList.remove('hidden');const verdict=report.overall_verdict||'未形成正式结论',alert=['Juice混用','仅概率探针混用','可能非GPT'].includes(verdict),insufficient=!report.verdict_available||String(verdict).includes('证据不足'),target=report.fusiongate_target;$('#qualityVerdict').className='quality-verdict'+(alert?' alert':insufficient?' warning':'');$('#qualityVerdict').innerHTML='<div><span>综合结论</span><h2>'+esc(report.title_cn||verdict)+'</h2><p>'+esc(report.subtitle_cn||report.quality_note||(report.common_causes||[]).join('；')||'本次检测已完成')+(target?'<br>'+esc('锁定目标：'+qualityTargetText(target)):'')+'</p></div>';const network=report.network_summary||{},models=Array.isArray(report.possible_models)?report.possible_models:[],top=models[0]||{};$('#qualityReportMetrics').innerHTML=[['声明模型',report.claimed_model||'—'],['档位',report.preset||'—'],['成功请求',network.successful??0],['最终错误',network.final_errors??0],['HTTP 尝试',network.http_attempts??0],['最高相似模型',top.model||top.name||'—']].map(([label,value])=>'<div><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>').join('');const failed=report.failed_items||[],limits=[...(report.common_causes||[]),...(report.limitations||[])];$('#qualityFailedItems').innerHTML=failed.length?failed.map(x=>'<p>'+esc(qualityItemText(x))+'</p>').join(''):'<p class="result-ok">没有达到报告门槛的失败项</p>';$('#qualityLimitations').innerHTML=limits.length?limits.map(x=>'<p>'+esc(qualityItemText(x))+'</p>').join(''):'<p>无附加说明</p>';$('#qualityReportJSON').textContent=JSON.stringify(report,null,2)}
async function loadQualityReport(){try{renderQualityReport(await api('/api/admin/quality-detector/report'))}catch(e){notice('质量检测报告加载失败：'+e.message,true)}}
async function loadQualityStatus(){try{const status=await api('/api/admin/quality-detector/status');renderQualityStatus(status);if(status.report_available&&['complete','stopped'].includes(status.status)&&qualityReportSession!==status.session_id){qualityReportSession=status.session_id||'';await loadQualityReport()}if(['complete','stopped','error'].includes(status.status)){clearInterval(qualityPollTimer);qualityPollTimer=0}}catch(e){$('#qualityStatus').className='badge red';$('#qualityStatus').textContent='不可用';$('#qualityUpdated').textContent=e.message}}
async function startQualityDetection(){const target=selectedQualityTarget(),preset=$('#qualityPreset').value;if(!target)return notice('请选择可用的模型、上游渠道和凭据',true);$('#qualityStart').disabled=true;$('#qualityReport').classList.add('hidden');qualityReportSession='';try{await api('/api/admin/quality-detector/start',{method:'POST',body:JSON.stringify({preset,target_id:target.id})});notice('定向质量检测已开始：'+qualityTargetText(target));await loadQualityStatus();if(!qualityPollTimer)qualityPollTimer=setInterval(loadQualityStatus,5000)}catch(e){notice('启动质量检测失败：'+e.message,true);$('#qualityStart').disabled=false}}
