async function revealKey(id){const name=cache.keys.find(x=>x.id===id)?.name||'API Key';try{const d=await api('/api/admin/keys/'+id+'/reveal',{method:'POST'});openKeyModal(d.key,'复制 '+name,'完整密钥已临时解密显示；关闭弹窗后仍可再次按需复制。')}catch(e){notice('无法复制密钥：'+e.message,true)}}
