async function discoverModels(id,button){if(!id){notice('请先选择模型来源渠道',true);return}const original=button?.innerHTML;if(button){button.disabled=true;button.textContent='正在识别全部 Key…'}try{const d=await api('/api/admin/providers/'+id+'/discover-models',{method:'POST'});openModelPicker(id,d);const keys=d.keys||[],failed=keys.filter(x=>x.error),succeeded=keys.length-failed.length;if(failed.length)notice('已合并 '+succeeded+' 张 Key 的模型；'+failed.length+' 张识别失败，可在渠道设置的 Key 管理标签中单独重试',true)}catch(e){notice('模型识别失败：'+e.message,true)}finally{if(button){button.disabled=false;button.innerHTML=original}}}
function openModelPicker(providerId,d){const models=Array.isArray(d.models)?d.models:[];const active=models.filter(x=>x.existing).map(x=>x.id);modelPicker={providerId,models,selected:new Set(active),initial:new Set(active)};modelPickerBatchIds=[];$('#modelPickerSearch').value='';$('#modelPickerTitle').textContent='管理此渠道使用的模型';const unavailable=models.filter(x=>x.unavailable).length;$('#modelPickerSummary').textContent='识别到 '+d.discovered+' 个上游可用模型'+(d.skipped?'，另跳过 '+d.skipped+' 个不支持的模型':'')+(unavailable?'；'+unavailable+' 个使用中的模型本次未被上游返回，已为你保留':'')+'。勾选即启用，取消勾选即停止使用。';$('#modelPickerModal').classList.remove('hidden');renderModelPicker()}
function closeModelPicker(){$('#modelPickerModal').classList.add('hidden');modelPicker={providerId:0,models:[],selected:new Set(),initial:new Set()};modelPickerBatchIds=[]}
function filteredPickerModels(){const q=$('#modelPickerSearch').value.trim().toLowerCase();return modelPicker.models.map((model,index)=>({model,index})).filter(x=>!q||(x.model.id+' '+(x.model.display_name||'')+' '+(x.model.capabilities||'')+' '+(x.model.public_names||[]).join(' ')).toLowerCase().includes(q))}
function modelPickerStatus(model){const selected=modelPicker.selected.has(model.id),wasActive=modelPicker.initial.has(model.id),aliases=(model.public_names||[]).filter(x=>x!==model.id),mapped=aliases.length?' · 映射为 '+aliases.join(' / '):'';if(model.unavailable)return selected?badge('使用中'+mapped+' · 上游未返回','orange'):badge('将停止 · 上游未返回','red');if(wasActive)return selected?badge('使用中'+mapped,'green'):badge('将停止','red');if(selected)return badge('将启用','green');if(model.excluded)return badge('已停用','orange');return badge(model.capabilities==='image'?'可启用 · 图像':'可启用 · 对话','blue')}
function modelPickerClass(model){const selected=modelPicker.selected.has(model.id),wasActive=modelPicker.initial.has(model.id);return [model.unavailable?'unavailable':'',wasActive?(selected?'in-use':'stopping'):(selected?'adding':model.excluded?'restorable':'')].filter(Boolean).join(' ')}
function renderModelPicker(){const rows=filteredPickerModels();const list=$('#modelPickerList');list.innerHTML=rows.length?rows.map(({model,index})=>'<label class="model-option '+modelPickerClass(model)+'"><input class="model-choice" type="checkbox" data-index="'+index+'" '+(modelPicker.selected.has(model.id)?'checked':'')+' onchange="modelSelectionChanged('+index+',this.checked)"><span class="model-option-main"><span class="model-option-name">'+esc(model.id)+'</span>'+(model.display_name?'<span class="model-option-display">'+esc(model.display_name)+'</span>':'')+'</span>'+modelPickerStatus(model)+'</label>').join(''):'<div class="model-picker-empty">没有符合搜索条件的模型</div>';updateModelSelection()}
function modelSelectionChanged(index,checked){const model=modelPicker.models[index];if(!model)return;checked?modelPicker.selected.add(model.id):modelPicker.selected.delete(model.id);renderModelPicker()}
function selectVisibleModels(checked){filteredPickerModels().forEach(({model})=>{checked?modelPicker.selected.add(model.id):modelPicker.selected.delete(model.id)});renderModelPicker()}
function selectedModelIDs(){return [...modelPicker.selected]}
function modelSelectionDiff(){const added=selectedModelIDs().filter(id=>!modelPicker.initial.has(id));const removed=[...modelPicker.initial].filter(id=>!modelPicker.selected.has(id));return{added,removed}}
function updateModelSelection(){const count=modelPicker.selected.size,{added,removed}=modelSelectionDiff();const changeParts=[];if(added.length)changeParts.push('新增 '+added.length);if(removed.length)changeParts.push('停止 '+removed.length);$('#modelPickerCount').textContent='当前启用 '+count+' 个模型'+(changeParts.length?' · '+changeParts.join(' · '):' · 尚未修改');const button=$('#modelPickerImport');button.disabled=!changeParts.length;button.innerHTML=icon('i-check')+(changeParts.length?'保存模型设置（'+changeParts.join(' · ')+'）':'没有修改')}
async function saveModelSelection(){const models=selectedModelIDs(),{added,removed}=modelSelectionDiff(),batch=modelPickerBatchIds;if(!added.length&&!removed.length)return;const button=$('#modelPickerImport');button.disabled=true;button.textContent='正在保存模型设置…';try{if(batch.length){const d=await api('/api/admin/providers/batch',{method:'POST',body:JSON.stringify({provider_ids:batch,action:'models',models})});authFileSelection.clear();closeModelPicker();notice('已批量更新 '+d.affected+' 份认证文件的模型：新增 '+d.added+'，停止 '+d.removed)}else{const d=await api('/api/admin/providers/'+modelPicker.providerId+'/models',{method:'PUT',body:JSON.stringify({models})});closeModelPicker();notice('模型设置已保存：新增 '+d.added+' 个，停止 '+d.removed+' 个，继续使用 '+d.existing+' 个')}await load()}catch(e){notice('模型设置保存失败：'+e.message,true);updateModelSelection()}}
async function batchModelsAuthFiles(){const selected=[...authFileSelection];if(!selected.length)return notice('请先勾选认证文件',true);const button=$('#authBatchModelsButton'),original=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='正在识别…'}try{const d=await api('/api/admin/providers/'+selected[0]+'/discover-models',{method:'POST'});openModelPicker(selected[0],d);modelPickerBatchIds=selected;$('#modelPickerTitle').textContent='批量选择模型（'+selected.length+' 份认证文件）';$('#modelPickerSummary').textContent='以第一份认证文件识别到的模型为准，将应用到所选 '+selected.length+' 份同类型认证文件。勾选即启用，取消勾选即停止使用。'}catch(e){notice('识别模型失败：'+e.message,true)}finally{if(button){button.disabled=false;button.innerHTML=original}}}
async function removeItem(type,id){if(!confirm(type==='keys'?'确认彻底删除这把 API Key？删除后无法恢复。':'确认删除？关联配置可能一并删除。'))return;try{await api('/api/admin/'+type+'/'+id,{method:'DELETE'});notice(type==='keys'?'密钥已彻底删除':'已删除');load()}catch(e){notice(e.message,true)}}
function bindForm(id,handler,panel){
  $('#'+id).onsubmit=async e=>{
    e.preventDefault();const button=e.submitter;button.disabled=true;const original=button.innerHTML;button.textContent='处理中…';
    try{
      const o=Object.fromEntries(new FormData(e.target));const result=await handler(o);e.target.reset();if(id==='keyForm')resetKeyPermissions();togglePanel(panel,false);
      if(result.key)openKeyModal(result.key)
      else if(result.model_discovery){const d=result.model_discovery;if(d.status==='ok')openModelPicker(result.id,d);else notice('渠道已保存，但模型识别失败：'+d.error,true)}
      else notice('保存成功');
      load();
    }catch(err){notice(err.message,true)}finally{button.disabled=false;button.innerHTML=original}
  };
}
