function routeOrder(name){return (cache.routes||[]).filter(x=>x.public_name===name).sort((a,b)=>(Number(a.sort_order)-Number(b.sort_order))||(a.id-b.id))}
async function saveRouteOrder(name,ids){try{await api('/api/admin/routes/reorder',{method:'PATCH',body:JSON.stringify({public_name:name,route_ids:ids})});ids.forEach((id,index)=>{const route=cache.routes.find(x=>Number(x.id)===Number(id));if(route)route.sort_order=index});renderRoutes();notice('上游渠道位置已更新')}catch(e){notice('更新渠道位置失败：'+e.message,true);await load()}}
