function animateCountUp(){document.querySelectorAll('.stat-value,.usage-stat-value').forEach(el=>{const orig=el.textContent.trim();const m=orig.match(/^([^0-9]*)([0-9][0-9,.]*)(.*)$/);if(!m)return;const num=parseFloat(m[2].replace(/,/g,''));if(isNaN(num)||num<=0)return;const pre=m[1],suf=m[3],t0=performance.now(),dur=700;function tick(now){const t=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-t,3),v=num*e;const dec=num>=1000?0:(num>=100?0:1);el.textContent=pre+v.toFixed(dec)+suf;if(t<1)requestAnimationFrame(tick);else el.textContent=orig}requestAnimationFrame(tick)})}
